-- Post-conditions: every FK must hold now that checking is back on. A silent
-- orphan surfaces later as a learner whose attempts have no module.
do $chk$
declare n int;
begin
  select count(*) into n from payroll_iq.users u
    left join auth.users a on a.id = u.id where a.id is null;
  if n <> 0 then raise exception 'payroll_iq.users with no auth row: %', n; end if;

  select count(*) into n from payroll_iq.users u
    left join payroll_iq.organisations o on o.id = u.org_id
   where u.org_id is not null and o.id is null;
  if n <> 0 then raise exception 'users pointing at a missing org: %', n; end if;

  select count(*) into n from payroll_iq.quiz_attempts q
    left join payroll_iq.users u on u.id = q.learner_id where u.id is null;
  if n <> 0 then raise exception 'quiz_attempts with no learner: %', n; end if;
end $chk$;
