INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('72a589b9-98af-4bc4-b1f4-7af0d73f2466', 'cb3699a6-74dc-42b1-8b48-6433ea2fb2de', 'user', 'can you tell me the laws surrounding overtime for restaurant staff in sydney', NULL, NULL, 0, 0, '2026-08-19 02:02:10.306608+00', NULL, NULL, NULL, NULL);
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('24a6d87b-4053-4c25-b7e3-ce4fd802f5c3', 'cb3699a6-74dc-42b1-8b48-6433ea2fb2de', 'assistant', '<p>Determining which award applies is an HR/legal obligation. We partner with Workplace Law, who can give specific advice for a fee, let me know if you''d like their details. </p>
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('d55ba55b-83df-4943-b045-0b61716515d9', '5cd910e9-6d1d-4281-9a30-379a8495612e', 'user', 'How much long service leave do I have to pay for someone who is terminated after 9 years of service', NULL, NULL, 0, 0, '2026-08-19 10:32:10.195156+00', NULL, NULL, NULL, NULL);
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('7e68920e-6faf-4f9d-9f80-7914f2a6df91', '5cd910e9-6d1d-4281-9a30-379a8495612e', 'assistant', '<p>To determine the correct long service leave entitlement and calculation method for an employee terminating with 9 years of service, could you please confirm which state or territory the employee is located in?</p>', NULL, NULL, 0, 0, '2026-08-19 10:32:10.225689+00', '4c813ba9-3799-4520-9d2e-5d95244c2e11', 'complete', false, 'The response clarifies the need for additional information regarding the employee''s location to provide the correct general entitlement rules, which is a standard step for answering leave entitlement queries.');
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('d75edfcd-d5a3-43f3-a053-9b1da45ac87f', '60d7999e-1bab-4382-b01a-a8badc4144d2', 'user', 'What is the superannuation rate?', NULL, NULL, 0, 0, '2026-08-28 04:58:22.059858+00', NULL, NULL, NULL, NULL);
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('0655601b-5300-476b-8600-23f104f42662', '60d7999e-1bab-4382-b01a-a8badc4144d2', 'assistant', '<p>For the 2026-27 financial year, the current superannuation guarantee (SG) rate you must apply is 12%.</p>', NULL, NULL, 0, 0, '2026-08-28 04:58:22.080563+00', 'e24e54be-4738-4735-9c64-95b0b28a3128', 'complete', false, 'The question asks for a standard payroll rate, and the answer provides the specific, factual superannuation rate for the current financial year.');
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('6dcf8c95-05ea-4f15-bfc3-abeab94415ff', '60d7999e-1bab-4382-b01a-a8badc4144d2', 'user', 'How do you treat part days of unpaid or unapproved absences?', NULL, NULL, 0, 0, '2026-08-28 05:00:52.074592+00', NULL, NULL, NULL, NULL);
INSERT INTO payroll_iq.chat_messages (id, session_id, role, content, tool_calls, model, input_tokens, output_tokens, created_at, research_query_ref, research_status, requires_escalation, escalation_explanation) VALUES ('1d155519-62e5-4f61-8334-9356103c8504', '60d7999e-1bab-4382-b01a-a8badc4144d2', 'assistant', '<p>When processing a partial-day unpaid or unapproved absence, you should reduce the employee''s gross pay by the value of the unpaid ordinary hours not worked. For salaried or monthly paid employees, convert their salary to an hourly equivalent based on their employment contract, award, or enterprise agreement to calculate the deduction. </p>
