INSERT INTO payroll_iq.platform_settings (key, value, description, updated_at, updated_by) VALUES ('playback.archive_fallback_global', 'false', 'When true, every module with a verified MP4 archive plays from that archive instead of its Synthesia embed. Turn this on when Synthesia is known to be down; turn it off when they are back. Modules with no archive are unaffected and keep serving the embed.', '2026-07-29 07:11:45.660272+00', NULL);
INSERT INTO payroll_iq.platform_settings (key, value, description, updated_at, updated_by) VALUES ('chat.enabled_personas', '["learner", "manager"]', 'Which AI-chat personas are live, as a jsonb array of "learner" | "manager" | "admin". Seeded [] (dark). The /api/chat gate refuses any persona not in this list, so enabling the learner tutor is setting this to ["learner"] — a runtime flip, not a deploy.', '2026-07-31 01:28:52.707693+00', NULL);
INSERT INTO payroll_iq.platform_settings (key, value, description, updated_at, updated_by) VALUES ('chat.research_enabled', 'true', 'Whether Beryl research mode is live in the chat widget (feature 073), as a jsonb boolean. Seeded false (dark). When true, the learner and manager chat surfaces show a Chat | Beryl Research toggle; the /api/chat/research gate refuses every request while false. A runtime flip, not a deploy.', '2026-08-19 00:54:58.167982+00', NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0c02768a-8062-4b75-ab5d-800fc56be559', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which of the following payments are not ''Qualifying Earnings'' according to the ATO?', '[{"id": "A", "text": "Afternoon and Night Shift penalty rates"}, {"id": "B", "text": "Commission payments"}, {"id": "C", "text": "Overtime"}, {"id": "D", "text": "Christmas bonus"}]', '{"choice_id": "C"}', 'Under SGR 2009/2, overtime is remuneration for work performed outside ordinary hours of work and is therefore excluded from Ordinary Time Earnings, whereas shift penalties, commissions and bonuses generally form part of OTE.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9ceb7b49-7872-49aa-bd82-d687bfbac082', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The superannuation guarantee rate effective 1 July 2026 is:', '[{"id": "A", "text": "0.095"}, {"id": "B", "text": "0.12"}, {"id": "C", "text": "0.105"}, {"id": "D", "text": "0.115"}]', '{"choice_id": "B"}', 'Under the Superannuation Guarantee (Administration) Act, the SG rate increased in annual steps and reached its final rate of 12% on 1 July 2025.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a6777fa4-c80e-4c4d-bf67-e2b40aada97b', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The cents per kilometre ATO reasonable rate for FY 2026-27 is:', '[{"id": "A", "text": "72 cents"}, {"id": "B", "text": "78 cents"}, {"id": "C", "text": "91 cents"}, {"id": "D", "text": "96 cents"}]', '{"choice_id": "C"}', 'The ATO set the cents per kilometre rate for calculating work-related car expense deductions at 91 cents per kilometre for the 2026-27 financial year.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3532d787-3a44-46ca-87db-0a6442758176', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'What is the High-income threshold for financial year 2026-27?', '[{"id": "A", "text": "190100"}, {"id": "B", "text": "162000"}, {"id": "C", "text": "162500"}, {"id": "D", "text": "158500"}]', '{"choice_id": "A"}', 'For the 2026-27 financial year, the Fair Work high-income threshold was set at $190,100, above which employees not covered by an award or enterprise agreement are excluded from unfair dismissal protections and can be subject to a guarantee of annual earnings.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4af7fa17-70f1-4ef3-bcec-d19aa6583aa5', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'An employee''s Whole of Income Cap for 2026-27 is calculated using which figure?', '[{"id": "A", "text": "270000"}, {"id": "B", "text": "180000"}, {"id": "C", "text": "245000"}, {"id": "D", "text": "260000"}]', '{"choice_id": "B"}', 'The whole-of-income cap is a fixed $180,000, reduced by other taxable income the employee earns in the income year to determine the amount of an ETP taxed at concessional rates. Amounts above the remaining cap are taxed at the top marginal rate.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('33b7a45f-a520-47a8-b945-e717375c27b9', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The superannuation guarantee rate effective 1 July 2026 is:', '[{"id": "A", "text": "0.095"}, {"id": "B", "text": "0.115"}, {"id": "C", "text": "0.105"}, {"id": "D", "text": "0.12"}]', '{"choice_id": "D"}', 'The superannuation guarantee rate is 12% as at 1 July 2026.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4b05e0bc-ba62-45cd-bb0b-dbc39a46258d', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'An employers obligation to contribution superannuation is limited to the maximum superannuation contribution base per quarter. The quarterly maximum superannuation contribution base for 2023 -24 is', '[{"id": "A", "text": "62270"}, {"id": "B", "text": "60220"}, {"id": "C", "text": "249080"}, {"id": "D", "text": "27500"}]', '{"choice_id": "A"}', 'The ATO set the maximum super contribution base for the 2023-24 financial year at $62,270 per quarter, above which employers are not required to pay the 11% super guarantee.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('657d7ff5-ba7a-4588-9eca-c4b1eeb722e8', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Junlie has been employed by Sphere Ltd for 8.5 years and is 42 years old when she is advised that her role is being made redundant. The value of Junlie’s redundancy pay is $32,500. Using the genuine redundancy tax-free component rates for FY 2026-27, how much of Junlie’s redundancy pay is tax free?', '[{"id": "A", "text": "The whole $32,500 is tax free"}, {"id": "B", "text": "$17,979 is tax free"}, {"id": "C", "text": "$11 985 is tax free"}, {"id": "D", "text": "The whole $32,500 is taxable as an ETP"}]', '{"choice_id": "A"}', 'For FY2026-27 the genuine redundancy tax-free limit is $13,598 base plus $6,801 per completed year of service', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('71a1eb5e-9a32-4d91-adef-e0775842ee24', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Jamie has been employed by Sphere Ltd for 7.5 years and is 71 years old when he is advised that his role is being made redundant. The value of Jamie’s redundancy pay is $53,900. How much of Jamie''s redundancy pay is tax free?', '[{"id": "A", "text": "$11,985 is tax free"}, {"id": "B", "text": "$41,958 is tax free"}, {"id": "C", "text": "None - the whole amount of $53,900 is taxable as an ETP"}, {"id": "D", "text": "The whole amount of $53,900 is tax free"}]', '{"choice_id": "C"}', 'Genuine redundancy tax-free concessional treatment only applies if the employee is below age-pension age (currently 67) on the day of dismissal; as Jamie is 71, he fails this ATO condition, so no amount is tax free and the entire payment is taxed as an ETP.', 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a37ea843-545e-45f7-8e1f-21624b94b507', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'The ETP Cap for the financial year 2026-27 is:', '[{"id": "A", "text": "180000"}, {"id": "B", "text": "225000"}, {"id": "C", "text": "230000"}, {"id": "D", "text": "270000"}]', '{"choice_id": "D"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5a5569fa-47b7-4a2b-b1da-1aa40dbc6aec', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which of the following statements is not true?', '[{"id": "A", "text": "Employers have to keep written time and wages records for their employees for seven years"}, {"id": "B", "text": "Managers or higher income employees may not be covered by a modern award even if one applies to the industry in which they work"}, {"id": "C", "text": "Fair Work Inspectors use time and wages records to find out what an employee is entitled to and whether they''re getting those entitlements"}, {"id": "D", "text": "Employee time and wage records must be kept as a hard copy that is easily accessible to Fair Work Inspectors"}]', '{"choice_id": "D"}', 'Under the Fair Work Regulations, time and wages records can be kept electronically as long as they are legible, in English, and accessible to Fair Work Inspectors—they do not have to be hard copies, making D the false statement.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c9aeb630-3fa8-4a2c-936f-278c7968d20f', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'For a large business employer (15 or more employees) the Casual Employment information statement (CEIS) must be given to all new casuals employees:', '[{"id": "A", "text": "When they ask for it."}, {"id": "B", "text": "Upon commencement of employment, at 6 months, at 12 months and every 12 months thereafter"}, {"id": "C", "text": "On commencement of employment"}, {"id": "D", "text": "It is up to the employee to get a copy themselves from the Fair Work Ombudsman."}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a19932ae-a0c4-42b9-ad40-d4cada63a0d4', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Under the Fair Work system, which of the following is NOT one of the National Employment Standards'' 12 minimum entitlements?', '[{"id": "A", "text": "Community service leave"}, {"id": "B", "text": "Long service leave"}, {"id": "C", "text": "Annual wage review adjustments"}, {"id": "D", "text": "The Fair Work Information Statement"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0124a592-5ed9-4ac3-b076-11f3e83a46a8', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which employees generally remain in the state industrial relations system unless covered by a registered national system agreement, in NSW, SA and QLD?', '[{"id": "A", "text": "All private sector employees"}, {"id": "B", "text": "State public sector and local government employees"}, {"id": "C", "text": "Casual employees only"}, {"id": "D", "text": "Employees earning above the high income threshold"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a8be20b2-a92f-410e-afba-c22ca5bf505d', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'In the hierarchy of industrial instruments, what is the correct order of precedence from the floor upward?', '[{"id": "A", "text": "Individual contract, then modern award, then NES"}, {"id": "B", "text": "NES, then modern award or registered agreement, then individual contract"}, {"id": "C", "text": "Modern award, then NES, then registered agreement"}, {"id": "D", "text": "Registered agreement, then NES, then individual contract"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('96bfe9dd-5f5b-49dd-804e-1177c3075b5e', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under an award like the Hospitality Award, "ordinary hourly rate" is often defined to include:', '[{"id": "A", "text": "The minimum rate only, with no allowances loaded in"}, {"id": "B", "text": "The minimum rate plus all purpose allowances"}, {"id": "C", "text": "The minimum rate plus superannuation"}, {"id": "D", "text": "The minimum rate plus overtime already worked"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('73e0bcc7-d780-4c41-80e0-d9c4a9f94a61', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Since the legal definition of casual employment changed on 26 March 2021, casual status is assessed:', '[{"id": "A", "text": "At the end of each year of service"}, {"id": "B", "text": "At the time the offer of employment is accepted"}, {"id": "C", "text": "Only when the employee requests casual conversion"}, {"id": "D", "text": "By the number of hours worked in the previous quarter"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('67b95995-ffe4-4d29-aa63-4befe0a52eae', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Under the casual conversion rules that changed on 26 August 2024, a casual employee in a medium or large business with at least 6 months'' service can:', '[{"id": "A", "text": "Request conversion themselves, with the employer given 21 days to respond"}, {"id": "B", "text": "Be automatically converted without any request"}, {"id": "C", "text": "Only convert if the employer proactively reviews their anniversary"}, {"id": "D", "text": "Never convert unless the award is silent on casual conversion"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5799b873-ac48-4a47-9a6b-5e256f204707', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Guaranteed earnings used to test whether a high income earner is genuinely award free include wages and guaranteed allowances, but exclude:', '[{"id": "A", "text": "Base salary"}, {"id": "B", "text": "Non-monetary benefits agreed in writing"}, {"id": "C", "text": "Commissions, bonuses, overtime, reimbursements and superannuation"}, {"id": "D", "text": "The classification rate under the award"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2aafa9e2-b540-4d5b-a2d9-4507818fe8c0', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under an award-specific annualised salary (such as under the Clerks Award), employers must maintain:', '[{"id": "A", "text": "A three-year retrospective review only"}, {"id": "B", "text": "An outer limits letter, ongoing timesheets, and an annual reconciliation"}, {"id": "C", "text": "A single annual payslip showing the total package"}, {"id": "D", "text": "No specific record keeping beyond the general minimum"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c6f2e7e9-d266-4057-9d60-5ed7721f1673', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'Which state''s formula for full-time "ordinary pay" for long service leave purposes uniquely includes shift penalties, an inclusion most other states exclude?', '[{"id": "A", "text": "Tasmania"}, {"id": "B", "text": "Western Australia"}, {"id": "C", "text": "South Australia"}, {"id": "D", "text": "Queensland"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('76e8be1f-efac-4f95-a9f9-619f49c7963c', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'The tax free portion of genuine redundancy payment:', '[{"id": "A", "text": "Appears as the \"ETP tax free component\" on an income statement."}, {"id": "B", "text": "Is indexed each year."}, {"id": "C", "text": "Is not determined based on an employees years of service."}, {"id": "D", "text": "Is the amount less than the ETP cap."}]', '{"choice_id": "B"}', 'The tax-free limit of a genuine redundancy payment is set by a base amount plus an amount for each completed year of service, both of which the ATO indexes annually. It is not part of the ETP tax-free component and is based on years of service, ruling out the other options.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('8616276b-f893-46c3-ba69-da7d839737be', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'An employee does not accrue annual leave whilst on paid:', '[{"id": "A", "text": "Long service leave"}, {"id": "B", "text": "Government funded parental leave"}, {"id": "C", "text": "Personal leave"}, {"id": "D", "text": "Annual leave"}]', '{"choice_id": "B"}', 'Under the NES, annual leave continues to accrue during other paid leave (personal, annual and long service leave), but the Australian Government''s Parental Leave Pay is treated like unpaid parental leave for accrual purposes, so annual leave does not accrue while receiving it.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f84a0f90-4684-4711-bc82-c4918d3560b1', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Payments under the government''s paid parental leave scheme', '[{"id": "A", "text": "Are subject to PAYG."}, {"id": "B", "text": "Accrue annual leave and personal leave entitlements."}, {"id": "C", "text": "Are subject to Payroll Tax"}, {"id": "D", "text": "Are subject to SG (ie. the employer must make superannuation contributions on these payments)"}]', '{"choice_id": "A"}', 'Government Paid Parental Leave payments are treated as taxable income, so employers must withhold PAYG tax when passing them on to eligible employees; they don''t attract super guarantee, payroll tax, or accrue leave entitlements.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('76235c55-e152-40c8-834b-4e63d095b7f5', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which of the following is a key indicator that a worker is more likely a genuine independent contractor rather than an employee?', '[{"id": "A", "text": "They are paid for time worked"}, {"id": "B", "text": "They must perform the work personally"}, {"id": "C", "text": "They are free to delegate or subcontract the work to others"}, {"id": "D", "text": "The business controls how and when the work is done"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9f1441ca-ac7f-4cda-96ab-9815afd76112', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Superannuation guarantee obligations can still apply to a contractor who is:', '[{"id": "A", "text": "Paid wholly or principally for their labour, even if paid entirely through accounts payable"}, {"id": "B", "text": "Paid only for a result achieved at a fixed price"}, {"id": "C", "text": "Free to delegate the work to a subcontractor"}, {"id": "D", "text": "Genuinely running their own business with their own equipment"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('94d4f361-8b55-4b00-9c15-9be6528f77f4', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'A trainee''s pay rate is generally set under:', '[{"id": "A", "text": "The relevant industry award directly"}, {"id": "B", "text": "The Miscellaneous Award, Schedule E, based on wage level and years out of school"}, {"id": "C", "text": "The Fair Work Information Statement"}, {"id": "D", "text": "A fixed national trainee wage set by the ATO"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6eb0c976-60a0-4286-9061-dde8f6a37e15', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'The Miscellaneous Award is best described in the guide as:', '[{"id": "A", "text": "An award exclusively for apprentices"}, {"id": "B", "text": "A safety net that can cover trainees and workers who don''t fit any industry or occupational award"}, {"id": "C", "text": "An award that only applies to casual employees"}, {"id": "D", "text": "A now-repealed transitional award"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4b15727f-b198-4fac-9f8f-7a87f3f2dbe1', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The superannuation guarantee rate effective 1 July 2023 is:', '[{"id": "A", "text": "9.5%"}, {"id": "B", "text": "11.5%"}, {"id": "C", "text": "10.5%"}, {"id": "D", "text": "11%"}]', '{"choice_id": "D"}', 'Under the legislated SG rate increases, the superannuation guarantee rose to 11% effective 1 July 2023, on its way to 12% by 1 July 2025.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:51.077719+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('de382a1d-29a2-4c6f-a8c8-308684b72ec6', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'Payslips must be given to an employee:', '[{"id": "A", "text": "when they request it"}, {"id": "B", "text": "within 1 working day of pay day"}, {"id": "C", "text": "Within 1 week of pay day"}, {"id": "D", "text": "Within 7 days of pay"}]', '{"choice_id": "B"}', 'Under the Fair Work Regulations, employers must issue a payslip within one working day of paying an employee, regardless of whether the employee is on leave or requests it.', 1, 'human', 'live', NULL, '2026-06-30 08:43:12.915277+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('525f5d1a-fc4f-4d9e-8d55-39949e1350e0', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'The Casual Employment information statement (CEIS) must be given to all new casual employees:', '[{"id": "A", "text": "When they ask for it."}, {"id": "B", "text": "Upon commencement of employment."}, {"id": "C", "text": "After the 27th of September 2021."}, {"id": "D", "text": "It is up to the employee to get a copy themselves from the Fair Work Ombudsman."}]', '{"choice_id": "B"}', 'Under the Fair Work Act, employers must give every new casual employee the Casual Employment Information Statement as soon as practicable after they start work (i.e. upon commencement).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('46744baf-dc21-482d-b930-68a0837783da', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'An eligible employee choosing their superannuation fund is not required to provide:', '[{"id": "A", "text": "A complying fund letter."}, {"id": "B", "text": "Evidence that the fund will accept contributions."}, {"id": "C", "text": "The employees last superannuation statement."}, {"id": "D", "text": "Fund details and member number."}]', '{"choice_id": "C"}', 'When completing a Standard Choice form, an employee must supply their fund''s details, member number, ABN, and evidence the fund is complying and will accept the employer''s contributions—but they are not required to hand over their most recent super statement.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a3b050f6-50c9-4e85-ac36-f21580b932ae', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'A large business employer is required to lodge Payroll Tax returns:', '[{"id": "A", "text": "Once a year."}, {"id": "B", "text": "Monthly and annually."}, {"id": "C", "text": "Not on the months that are nil."}, {"id": "D", "text": "Quarterly."}]', '{"choice_id": "B"}', 'Payroll tax is administered by state/territory revenue offices, and larger employers must lodge monthly returns throughout the year plus an annual reconciliation return to true-up their liability.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('b7a31a02-6610-4390-bbb0-7af4210352bb', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'Which of the following statements is incorrect?', '[{"id": "A", "text": "If you make a finalisation declaration during a financial year, you do not need to provide the employee with a part-year payment summary"}, {"id": "B", "text": "You cannot amend finalised information reported through STP"}, {"id": "C", "text": "If you finalise an employee partway through the financial year, the pre-fill will not be available until after the end of the financial year"}, {"id": "D", "text": "If you identify the need to amend details after making a finalisation declaration you should submit these via STP as soon as possible"}]', '{"choice_id": "B"}', 'Under Single Touch Payroll you can amend finalised year-to-date information by resubmitting through your STP-enabled software (option D), so the claim that finalised STP information cannot be amended is false, making B the incorrect statement.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('ee510921-0444-418f-9dbe-29be83a58e9b', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'STP requires employers to report payments such as; salary & wages, PAYG withholding and Superannuation information directly to the ATO;', '[{"id": "A", "text": "by the end of the year."}, {"id": "B", "text": "before month end."}, {"id": "C", "text": "on or before the date payment is made."}, {"id": "D", "text": "before the next pay run."}]', '{"choice_id": "C"}', 'Single Touch Payroll (STP) requires employers to report payroll information to the ATO on or before the date the payment is made to employees, at the same time as processing each pay event.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('bc92c21e-5774-4801-90ac-3283e210182f', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'For most employees covered by the Long Service Leave Acts in each jurisdiction, LSL accrues at the rate of 8.667 weeks for 10 years’ service.  This is for all States and Territories except:', '[{"id": "A", "text": "Tasmania and South Australia"}, {"id": "B", "text": "Northern Territory and South Australia"}, {"id": "C", "text": "Tasmania and ACT"}, {"id": "D", "text": "ACT and Northern Territory"}]', '{"choice_id": "B"}', 'In most jurisdictions LSL accrues at 8.667 weeks per 10 years, but the Northern Territory and South Australia are the exceptions, providing 13 weeks after 10 years'' service.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('91e3da44-8760-4df1-af41-d2d73e1420ce', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Which of the following payments are not Employment Termination Payments (ETPs)?', '[{"id": "A", "text": "Payment in lieu of notice"}, {"id": "B", "text": "Ex-gratia payment"}, {"id": "C", "text": "Unused annual and long service leave payments on termination"}, {"id": "D", "text": "Unused personal leave and RDO payments on termination"}]', '{"choice_id": "C"}', 'Under ATO rules, unused annual leave and long service leave paid on termination are specifically excluded from ETPs and are taxed under separate withholding schedules, whereas payments in lieu of notice and ex-gratia payments are ETPs.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a4c46ee5-3279-422a-aba4-17a5a2a30161', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'What are the maximum weekly hours of work for a Full-time employee under the first NES?', '[{"id": "A", "text": "Depends on the employees Award/Agreement"}, {"id": "B", "text": "37.5 hours"}, {"id": "C", "text": "40 hours"}, {"id": "D", "text": "38 hours"}]', '{"choice_id": "D"}', 'Under the National Employment Standards (Fair Work Act 2009), the maximum ordinary weekly hours for a full-time employee are 38 hours, plus any reasonable additional hours.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('94e4bbf5-b6eb-42cb-88f8-44ed1e8c1ab1', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Employers who get a request from an eligible employee for flexible working arrangements need, to respond within.', '[{"id": "A", "text": "28 days"}, {"id": "B", "text": "21 days"}, {"id": "C", "text": "3 months"}, {"id": "D", "text": "No time frame"}]', '{"choice_id": "B"}', 'Under the Fair Work Act''s National Employment Standards (NES), an employer must give a written response to a flexible working arrangement request within 21 days, stating whether the request is granted or refused.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9ec54e79-3068-4b5c-8e61-47d804e56a77', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Which statement is true about ? Unpaid Parental leave', '[{"id": "A", "text": "Public Holiday is not paid during Unpaid Parental leave"}, {"id": "B", "text": "Employees accrue Annual leave during Unpaid Parental leave"}, {"id": "C", "text": "Employees are entitled to unlimited time off."}, {"id": "D", "text": "Unpaid Parental leave counts towards Redundancy continuous service period."}]', '{"choice_id": "A"}', 'Under the NES, unpaid parental leave is unpaid, so employees do not receive payment for public holidays falling during that leave; no annual leave accrues during unpaid leave, entitlement is capped at 12 months (extendable), and while the period counts as continuous service it does not accrue certain entitlements.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('b3116612-d626-4049-9d16-47959d4972c0', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'How many weeks of annual leave does an employee need to have remaining if an award allows cashing out of annual leave?', '[{"id": "A", "text": "Employees can cash out all annual leave"}, {"id": "B", "text": "8 weeks"}, {"id": "C", "text": "Employees cannot cash out annual leave even if the award states so"}, {"id": "D", "text": "4 weeks"}]', '{"choice_id": "D"}', 'Under the Fair Work Act and the NES, an award or agreement that permits cashing out of annual leave must ensure the employee retains a balance of at least 4 weeks of accrued annual leave after the cash-out.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2ec111a0-a813-4e8e-99cc-3d8768481b40', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'What is one reason Sick and carer''s leave should not be taken', '[{"id": "A", "text": "Caring responsibly for sick parent"}, {"id": "B", "text": "Personal illness"}, {"id": "C", "text": "To attend a funeral"}, {"id": "D", "text": "Family emergency"}]', '{"choice_id": "C"}', 'Under the NES, personal/carer''s leave covers an employee''s own illness or injury and caring for an immediate family or household member who is sick or injured, or affected by an unexpected emergency. Attending a funeral is instead covered by compassionate (bereavement) leave, not sick and carer''s leave.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('732d135e-e20c-4b1a-8c7b-3a81df1107f3', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'What is not a reason why an employee can be paid below the National Minimum wage?', '[{"id": "A", "text": "The employee is not performing"}, {"id": "B", "text": "Junior Employee"}, {"id": "C", "text": "Apprentice"}, {"id": "D", "text": "Trainee"}]', '{"choice_id": "A"}', 'Under the Fair Work Act, lawful exceptions to the National Minimum Wage include junior employees, apprentices and trainees, who have their own award/wage rates. Poor performance is not a valid legal reason to pay below the minimum wage.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c7b66473-57d6-4fe6-b91a-19606e8fc2f1', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'What is the High-income threshold for financial year 2023-24?', '[{"id": "A", "text": "$167,500"}, {"id": "B", "text": "$162,000"}, {"id": "C", "text": "162,500"}, {"id": "D", "text": "$158,500"}]', '{"choice_id": "A"}', 'For the 2023-24 financial year, the Fair Work high-income threshold was set at $167,500, above which employees not covered by an award or enterprise agreement are excluded from unfair dismissal protections and can be subject to a guarantee of annual earnings.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:51.404944+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('71e6de11-ec47-4f41-a3e1-48cbe03b05e5', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'When does an employer need to provide an employee with their payslip', '[{"id": "A", "text": "Only when the employee requests it"}, {"id": "B", "text": "Within a week of pay day"}, {"id": "C", "text": "With one business day of pay day"}, {"id": "D", "text": "Within 21 days of pay day"}]', '{"choice_id": "C"}', 'Under the Fair Work Regulations, employers must issue a payslip to each employee within one working day of pay day, whether or not the employee is on leave.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:51.556761+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('fdd8660f-9142-4711-92a2-e71117d1dae2', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'When can an employer not direct an employee to take their annual leave?', '[{"id": "A", "text": "During a business shut down such as Christmas shutdown"}, {"id": "B", "text": "When the employee has excessive annual leave of 8 weeks"}, {"id": "C", "text": "When the employer wants them to"}, {"id": "D", "text": "When a shiftworker has an excessive annual leave of 10 weeks"}]', '{"choice_id": "C"}', 'Under the Fair Work Act and modern awards, an employer can only direct leave in limited, reasonable circumstances (e.g. shutdowns or excessive accruals of 8 weeks, or 10 weeks for shiftworkers); simply because the employer ''wants them to'' is not a lawful basis for a direction.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('26ed2991-3941-4a9a-92bd-4288a05b92f8', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'For family and domestic leave when can an employee not claim leave?', '[{"id": "A", "text": "When an employee is rostered to work and needs to attend court for FDV"}, {"id": "B", "text": "When an employee is rostered to work and needs to make arrangements for safety for FDV"}, {"id": "C", "text": "When an employee is rostered to work and needs accessing police services for FDV"}, {"id": "D", "text": "When an employee is not rostered to work and needs to attend court for FDV"}]', '{"choice_id": "D"}', 'Family and domestic violence leave under the NES can only be accessed when the employee needs to be absent from work they are rostered to perform; if they are not rostered on, there is no work to take leave from, so no leave can be claimed.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('73d798d2-5187-41a3-956f-9c46a9166b5d', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'How should Family and Domestic Violence leave taken be shown on an employee’s payslip?', '[{"id": "A", "text": "It should be shown as payment for performing work (eg;as much as like a regular pay as possible)"}, {"id": "B", "text": "Reported as family and domestic violence leave"}, {"id": "C", "text": "Shown as Special leave"}, {"id": "D", "text": "It should not be shown at all."}]', '{"choice_id": "A"}', 'To protect employee safety and confidentiality, Fair Work requires that paid family and domestic violence leave not be identified as such on a payslip; it should instead be recorded to look like ordinary pay (e.g. as ordinary hours worked, an allowance or other leave).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a3be0bbc-d730-4cca-855b-dcd7877bf8e0', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Alycia has worked for her employer full-time for 1 year and has taken 1 week of annual leave. Her employer has told her that she has to use the rest of her annual leave before the end of the year, otherwise she will lose it. Is Alycia’s employer, correct?', '[{"id": "A", "text": "Yes – you have to use your annual leave in the year you accrue it."}, {"id": "B", "text": "No – she can keep her annual leave for up to 5 years. However, if she hasn''t used it after 5 years it will expire."}, {"id": "C", "text": "No – annual leave accumulates indefinitely."}, {"id": "D", "text": "No - annual leave can only be used after the employee has been employed for 1 year"}]', '{"choice_id": "C"}', 'Under the National Employment Standards (Fair Work Act), annual leave accrues progressively and rolls over from year to year without expiring, so an employer cannot force forfeiture at year''s end (though excessive leave can sometimes be directed to be taken under an award/agreement).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('133801b2-2b2d-4abd-be6e-f587f33b47ca', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Jason took 8 days of sick (personal)/carer''s leave in his first year of full-time work. How many days of sick/carer''s leave does Jason have at the start of his second year?', '[{"id": "A", "text": "None – unused sick/carer''s leave expires at the end of each year."}, {"id": "B", "text": "2 days – sick/carer''s leave carries over."}, {"id": "C", "text": "12 days as the employee receives their personal leave upfront on their next anniversary"}, {"id": "D", "text": "Unlimited sick leave days"}]', '{"choice_id": "B"}', 'Under the NES, full-time employees accrue 10 days of paid personal/carer''s leave per year, and any unused balance carries over. Having used 8 of his 10 days, Jason carries over the remaining 2 days into his second year.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('27d535cb-54ee-4509-aa3a-ebc60d725ca0', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'Tony''s father has passed away and he needs to attend the funeral. Tony calls his boss Rebecca to ask for the day off. What should Rebecca tell Tony?', '[{"id": "A", "text": "Tony can have unpaid leave."}, {"id": "B", "text": "Tony should use his annual leave."}, {"id": "C", "text": "Tony should use his long service leave"}, {"id": "D", "text": "Tony can have 2 days of compassionate leave."}]', '{"choice_id": "D"}', 'Under the National Employment Standards, employees are entitled to 2 days of compassionate (bereavement) leave per occasion when a member of their immediate family, such as a parent, dies. This is paid for full-time and part-time employees.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0e1946d7-3156-4ebd-90dd-15fb89602f97', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'Greg works full-time at a mining company and is a member of his local State Emergency Service branch (SES). When there are bushfires in a nearby national park, the SES asks him to assist over two days. Can Greg take time off work to help?', '[{"id": "A", "text": "Yes – he has to use his annual leave."}, {"id": "B", "text": "Yes – he can take unpaid community service leave."}, {"id": "C", "text": "Yes – he can take the time off without informing his employer."}, {"id": "D", "text": "No – he should assist on the weekend only"}]', '{"choice_id": "B"}', 'Under the NES (Fair Work Act), employees can take unpaid community service leave to engage in voluntary emergency management activities with recognised bodies such as the SES; there is no set limit provided the time off is reasonable, though the employee must notify the employer.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f0c22985-38f1-4741-9df2-96a0540b4ec5', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Philip has recently turned 60 and would like to work from home 1 day per week. He has been working for his employer for 6 months. When will Philip be eligible to request flexible working arrangements under the Fair Work Act?', '[{"id": "A", "text": "Now."}, {"id": "B", "text": "Never."}, {"id": "C", "text": "Only when the employer chooses"}, {"id": "D", "text": "In another 6 months."}]', '{"choice_id": "D"}', 'Under the Fair Work Act (s65 NES), an employee must have completed at least 12 months of continuous service before they can request flexible working arrangements; as Philip has only 6 months, he must wait another 6 months.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4d6da67b-93c5-455f-8629-7114710de4a0', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Christian has been working full-time for his large business employer for 3.5 years, and his role is now being made redundant. How many weeks redundancy pay is Christian entitled to under the NES?', '[{"id": "A", "text": "6 weeks"}, {"id": "B", "text": "8 weeks"}, {"id": "C", "text": "7 weeks"}, {"id": "D", "text": "12 weeks"}]', '{"choice_id": "C"}', 'Under the NES redundancy pay scale, an employee with at least 3 years but less than 4 years of continuous service is entitled to 7 weeks'' pay, and Christian''s 3.5 years falls in that bracket.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3ed92262-fc68-4da5-81be-355b8e1125ce', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Lisa has been employed as a full-time childcare worker in a day care centre for 3 years and is covered by an award. Lisa decides to resign on the spot and not provide any notice. Can Lisa''s boss withhold any of her wages because she didn''t provide any notice?', '[{"id": "A", "text": "Maybe – her boss can check the award that covers her employment to see if they can withhold wages when an employee doesn''t give the required notice."}, {"id": "B", "text": "No – employees have the right to quit and walk out immediately."}, {"id": "C", "text": "Yes – the employer can deduct the full amount from the employees’ wages"}, {"id": "D", "text": "No – the employee will need to work the notice"}]', '{"choice_id": "A"}', 'Under the Fair Work Act and many modern awards, an employer may be permitted to withhold up to one week''s wages if an employee fails to give the minimum notice required, but only where the applicable award or registered agreement specifically allows it—so the boss must check the award first.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('613dae40-26ac-436e-aa4c-97af54540caa', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Philipa''s final day of work is tomorrow. Her employment is covered by an award. Her employer said that she will withhold Philipa''s final pay until she returns her uniforms. Philipa has unused annual leave that will need to be paid out, and wages up until her last day. When does Philipa''s employer need to make these payments?', '[{"id": "A", "text": "When the employer has the money available."}, {"id": "B", "text": "After Philipa returns her uniforms."}, {"id": "C", "text": "When the award specifies."}, {"id": "D", "text": "In the next regular pay run"}]', '{"choice_id": "C"}', 'Under the Fair Work Act and National Employment Standards, final pay timing is governed by the applicable award or registered agreement, so the employer must pay within the timeframe the award specifies (an employer generally cannot lawfully withhold final pay as a condition of returning property).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('be59fa6a-5737-44b9-9842-e3094785820e', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'James owns a manufacturing and distribution business and has 10 employees. He has decided to focus solely on distribution and needs to make his manufacturing employees redundant. As well as their pay and accumulated leave, what does Jame’s need to give these employees?', '[{"id": "A", "text": "Notice only."}, {"id": "B", "text": "Redundancy pay and notice."}, {"id": "C", "text": "Redundancy pay only."}, {"id": "D", "text": "No payment"}]', '{"choice_id": "A"}', 'Under the NES, businesses with fewer than 15 employees are classified as small business employers and are exempt from paying redundancy pay, so James only needs to provide notice of termination (plus pay and accrued leave).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f4ff9ad0-28cf-40e5-852d-93fe2f3e5b95', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Darren works part-time Wednesday to Friday in an office. Friday is a public holiday and the office will be closed, so Darren doesn''t have to work. Is Darren entitled to be paid for the day off?', '[{"id": "A", "text": "No, only if the employee works these hours"}, {"id": "B", "text": "No, they need to use their leave."}, {"id": "C", "text": "Yes, as they are normally rostered to work on the Friday, they will be paid their base rate"}, {"id": "D", "text": "Yes, as they are normally rostered to work on the Friday, they will be paid their base rate plus any penalty loadings they would ordinarily receive"}]', '{"choice_id": "C"}', 'Under the NES (Fair Work Act s116), an employee who is absent because a day is a public holiday is entitled to payment at their base rate of pay for the ordinary hours they would otherwise have worked; the base rate excludes penalties, loadings and allowances.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c4f06fdd-8848-44c3-8a19-bf5e097eb56f', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'Jamie has 2 casual employees who only work a couple of hours each week. Neither have computers and both told her that they aren''t interested in receiving printed pay slips. As such, Jamie has stopped giving them pay slips and got them to sign their records to acknowledge that they don''t want them. Is it okay for Jamie not to give her employees pay slips?', '[{"id": "A", "text": "Yes – her employees have told her that they don''t want them."}, {"id": "B", "text": "No – she still needs to provide them with a pay slip within 1 working day of their pay day."}, {"id": "C", "text": "No – she needs to provide a payslip at the end of each month."}, {"id": "D", "text": "Yes - she should file it stating the employee does not want a copy."}]', '{"choice_id": "B"}', 'Under the Fair Work Act 2009 (and Fair Work Regulations), employers must issue a pay slip to each employee within one working day of payday, regardless of whether the employee wants one; this obligation cannot be waived by employee consent.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('16c5fa4d-1094-4fe1-9042-a13e99cb5fe0', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Mohammed wants to know how much annual leave and sick (personal)/carer''s leave he has accumulated. A friend has told him that this information should be on his pay slip. Is Mohammed''s friend, correct?', '[{"id": "A", "text": "Yes, Annual leave and Personal leave should be shown on the payslip"}, {"id": "B", "text": "Yes, all leave balances should be shown on the payslip when they become entitled to it."}, {"id": "C", "text": "No, only Annual leave needs to be shown on the payslip."}, {"id": "D", "text": "No, leave does not need to be shown on the employees’ payslip, however if an employee asks for their balance their employer must tell them"}]', '{"choice_id": "D"}', 'Under the Fair Work Regulations 2009, pay slips are not required to display leave balances; however, employers must inform employees of their leave entitlements/balances upon request (and it''s considered best practice to show them).', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3e90afb0-15e9-4947-8c54-80f3c3078342', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Daphne is 19 years old and commencing work for the first time. She has applied for a Tax File Number with the ATO but is still waiting for it to arrive. On her Tax File Number declaration she has selected “I have made a separate application/enquiry to the ATO for a new or existing TFN”. What TFN substitution code should her employer enter into the payroll system?', '[{"id": "A", "text": "999 999 999"}, {"id": "B", "text": "111 111 111"}, {"id": "C", "text": "444 444 444"}, {"id": "D", "text": "333 333 333"}]', '{"choice_id": "B"}', 'When an employee has applied for a TFN but hasn''t yet received it, the ATO substitute code 111 111 111 is used, allowing a 28-day grace period before tax must be withheld at the top marginal rate.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('177500e2-3735-439d-adc9-a34fddd23261', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Shona is 19 years old and commencing work for the first time. She has applied for a Tax File Number with the ATO but is still waiting for it to arrive. On her Tax File Number declaration, she has selected “I have made a separate application/enquiry to the ATO for a new or existing TFN”. Her employer enters the TFN substitution code 111 111 111 into the payroll system. How many days does Shona have to provide her TFN to her employer before they have to change the substitution code to 000 000 000?', '[{"id": "A", "text": "7 days"}, {"id": "B", "text": "60 days"}, {"id": "C", "text": "14 days"}, {"id": "D", "text": "28 days"}]', '{"choice_id": "D"}', 'Under ATO rules, when an employee is awaiting a TFN the employer uses code 111 111 111, but the employee has 28 days to supply their TFN; after this the employer must switch to 000 000 000 and withhold at the top marginal rate.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('fc4775f6-1e61-4656-8394-7968d27e64eb', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'ABC Pty Ltd has paid their new employee Manish in an off -cycle pay run. When does ABC Pty Ltd have to report the off-cycle pay run through STP?', '[{"id": "A", "text": "Either in a pay event on or before the off -cycle payment date, or in the next regular pay event"}, {"id": "B", "text": "Never, off-cycle payments are not reportable"}, {"id": "C", "text": "Immediately on payment"}, {"id": "D", "text": "At the end of the financial year"}]', '{"choice_id": "A"}', 'Under ATO Single Touch Payroll rules, off-cycle payments can be reported either via a pay event on or before the payment date, or included in the next regular pay event.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6247221d-312e-4dc4-b88a-ac507c46476a', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Luke is the owner of a security business. The business has a registered agreement that has been in operation for the past 3 years. Luke has discovered that the base pay rates in the Security Services Industry Award are now higher than the base pay rate under the registered agreement. Does Luke need to pay the base pay rates under the registered agreement or the base pay rates under the award?', '[{"id": "A", "text": "Base pay rate under the registered agreement."}, {"id": "B", "text": "The National minimum wage set by the Fair Work Commission"}, {"id": "C", "text": "The employer needs to be increased by the National minimum wage percentage"}, {"id": "D", "text": "Base pay rate under the award."}]', '{"choice_id": "D"}', 'Under the Fair Work Act, an enterprise/registered agreement''s base rate of pay cannot be less than the base rate in the relevant modern award (the better off overall test and base rate guarantee). As the Security Services Industry Award rate is now higher, Luke must pay at least the award base rate.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3d4a71dd-deaa-4fb0-92a0-2bad506e888e', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Davina is the owner of a hairdressing business and has full-time and casual hairdressers. The Hair and Beauty Award covers her business. Davina knows that her casual employees aren''t entitled to receive paid annual leave, paid sick (personal)/carer''s leave or paid days off for public holidays. What pay rate should Davina pay her casual hairdressers?', '[{"id": "A", "text": "The award rate, plus a casual loading."}, {"id": "B", "text": "The same as her full-time hairdressers."}, {"id": "C", "text": "The national minimum wage."}, {"id": "D", "text": "The award rate, plus a casual loading, or free hair products in lieu of the casual loading (as long as the value is equal or higher)."}]', '{"choice_id": "A"}', 'Under the Fair Work system and modern awards like the Hair and Beauty Award, casual employees receive the applicable award base rate plus a 25% casual loading, which compensates them for not receiving paid leave and public holiday entitlements; loading cannot be substituted with goods like hair products.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('cf5d7601-abf7-4e3b-9ddc-a49f6223cd72', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'When calculating the PAYG Withholding on annual leave on termination using the marginal rate calculation:', '[{"id": "A", "text": "Do not withhold for any STSL debts"}, {"id": "B", "text": "Do not withhold for any HELP debt, but continue to withhold for other STSL debts"}, {"id": "C", "text": "Withhold for all STSL debts"}, {"id": "D", "text": "None of the above apply"}]', '{"choice_id": "A"}', 'Under the ATO''s Schedule 7 marginal rate method for unused leave on termination, study and training support loan (STSL) amounts are not included in the withholding calculation, so no additional amount is withheld for HELP or other STSL debts.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('73e07c89-389f-44d7-8bd9-ed401ca9f78f', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Jimmy is a cashier at the local fast food shop. One night, his manager counts the till and finds that it is under by a few dollars. Jimmy was the only person who used the till that night. When Jimmy was hired, he signed an agreement saying that till shortages could be deducted from his pay. Is it okay for Jimmy''s manager to make a deduction from his pay to cover the shortage?', '[{"id": "A", "text": "Yes - Jimmy can be held responsible for the till shortage as he was the only person operating the till that night and he''s signed an agreement saying that till shortages could be deducted from his pay."}, {"id": "B", "text": "No - It''s unlawful to make a deduction from Jimmy''s pay for the till shortage."}, {"id": "C", "text": "Yes – you can deduct it from wages only"}, {"id": "D", "text": "No – but you can make the employee work an extra shift to cover the costs."}]', '{"choice_id": "B"}', 'Under the Fair Work Act, deductions must be authorised and principally for the employee''s benefit; a clause allowing the employer to recover till shortages benefits the employer and is unreasonable, making the deduction unlawful even though Jimmy signed it.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('195bbeea-8cdc-4ad3-b5dc-2bfad7c34169', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Allowances paid for working conditions such as working at heights, in cold environments or in confined spaces are:', '[{"id": "A", "text": "Tax free and not subject to superannuation"}, {"id": "B", "text": "Subject to PAYG but not subject to superannuation"}, {"id": "C", "text": "Tax free and subject to superannuation"}, {"id": "D", "text": "Subject to both PAYG and superannuation"}]', '{"choice_id": "D"}', 'Disability or working-condition allowances (heights, cold, confined spaces) are paid to compensate for the nature of the work, form part of ordinary time earnings, so they are taxable under PAYG withholding and attract superannuation guarantee.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('43723e9c-0237-4cea-a44e-b234b11248b8', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Bonuses and commissions are taxed as follows:', '[{"id": "A", "text": "Using Schedule 5 – tax table for back payments, commissions, bonuses and similar payments"}, {"id": "B", "text": "They are tax free"}, {"id": "C", "text": "They are taxed as per the regular weekly, fortnightly or monthly tax table"}, {"id": "D", "text": "At a flat rate of 32%"}]', '{"choice_id": "A"}', 'The ATO''s Schedule 5 specifically provides the method for calculating withholding on back payments, commissions, bonuses and similar lump sum payments, ensuring the correct PAYG amount is withheld.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('95c30594-fdc8-48dc-9ab3-977f3001170e', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'When calculating the PAYG withholding on a lump sum back payment relating to the current financial year using Schedule 5, the employer:', '[{"id": "A", "text": "Must use Method A"}, {"id": "B", "text": "Must use Method B (i)"}, {"id": "C", "text": "Can choose to use either Method A, or Method B (i)"}, {"id": "D", "text": "Must calculate the withholding using both Method A and Method B (i), and then use the one most beneficial to the employee"}]', '{"choice_id": "C"}', 'Under ATO Schedule 5, for a lump sum back payment that relates to the current financial year (or accrued less than 12 months before payment), the employer may use either Method A or Method B(i); Method B(ii) is reserved for amounts accrued more than 12 months earlier.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('652373dc-8a41-48e5-a1dc-f3bf40c60117', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'In Schedule 5 – tax table for back payments, commissions, bonuses and similar payments, Method B (i) can be used:', '[{"id": "A", "text": "For all back payments, regardless of the financial year it relates to"}, {"id": "B", "text": "For back payments relating to specific periods in the current financial year only"}, {"id": "C", "text": "For all lump sum payments, including bonuses and commissions"}, {"id": "D", "text": "For back payments relating to a prior financial year only"}]', '{"choice_id": "B"}', 'Under ATO Schedule 5, Method B(i) applies to additional payments (back payments) that relate to specific periods within the current financial year, while Method B(ii) covers prior-year back payments and lump sums in arrears.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('62b429fa-f534-4ce1-bd67-2be382a8d15e', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Unused annual leave on redundancy is taxed:', '[{"id": "A", "text": "At 32%"}, {"id": "B", "text": "At 47%"}, {"id": "C", "text": "At 17%"}, {"id": "D", "text": "At marginal rates"}]', '{"choice_id": "A"}', 'When paid due to genuine redundancy, invalidity or early retirement scheme, unused annual leave is subject to a concessional flat withholding rate of 32% (30% plus 2% Medicare levy), per ATO rules, rather than being taxed at normal marginal rates.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:56.709709+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('37e5975a-90fd-441d-a922-f07a554f9cd9', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Shibani has been overpaid by her employer in the current financial year. The gross amount of the overpayment was $2,100, with $500 in PAYG withheld from the overpaid amount. Which of the following apply:', '[{"id": "A", "text": "Shibani’s employer can demand that she repay the full gross amount of $2,100 immediately"}, {"id": "B", "text": "Shibani and her employer can make an agreement to repay the net amount of $1,600 over a period negotiated between them"}, {"id": "C", "text": "Shibani’s employer can deduct the full gross amount of $2,100 from her next pay, without Shibani’s consent"}, {"id": "D", "text": "Shibani’s employer can deduct the net amount of $1,600 from her next pay, without Shibani’s consent"}]', '{"choice_id": "B"}', 'Under the Fair Work Act, an employer cannot unilaterally deduct an overpayment without written agreement; where recovered in the same financial year, only the net amount ($1,600) is repayable because the employer recovers the withheld PAYG from the ATO, so a mutually negotiated repayment arrangement applies.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1258b870-b678-4dc4-811f-19e5c6ab7e49', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'Lump Sum E reporting relates to:', '[{"id": "A", "text": "All back payments made"}, {"id": "B", "text": "Back payments relating the current financial year, but only if they exceed $1,200"}, {"id": "C", "text": "Back payments relating to prior financial years"}, {"id": "D", "text": "Back payments relating to a period of more than 12 months ago and that exceeds $1,200"}]', '{"choice_id": "D"}', 'Lump Sum E applies to back payments that accrued more than 12 months before the payment date and total $1,200 or more in a financial year, per ATO rules; such amounts must be reported separately so the employee can access lump sum in arrears tax offsets.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:49:21.030285+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('b02ad481-a62f-42bb-a7e5-04b6a7eabc29', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Veena has been employed by Sphere Ltd for 2.5 years and is 26 years’ old when she is advised that her role is being made redundant. The value of Veena’s redundancy pay is $29,200. Using the genuine redundancy tax-free component rates for FY 2023-24, how much of Veena’s redundancy pay is tax free?', '[{"id": "A", "text": "$26,970 is tax free"}, {"id": "B", "text": "$23,973 is tax free"}, {"id": "C", "text": "$17,979 is tax free"}, {"id": "D", "text": "The whole $29,200 is tax free"}]', '{"choice_id": "B"}', 'For FY 2023-24 the genuine redundancy tax-free amount is $11,985 base plus $5,994 per completed year of service (ATO rates). With 2 completed years: $11,985 + (2 × $5,994) = $23,973.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:52.126839+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('772541a6-eac7-43e7-a3e1-a152b9b29d82', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'Tran was incorrectly paid a bonus in May 2023, and her employer has only realised this in August 2023. As the overpayment was identified in a subsequent financial year, Tran’s employer must:', '[{"id": "A", "text": "Deduct the gross bonus amount from Tran’s next pay"}, {"id": "B", "text": "Deduct the net bonus amount from Tran’s next pay"}, {"id": "C", "text": "Un-finalise the prior FY for Tran, reverse the gross bonus amount and re-finalise the employee (and not adjust the tax). The employer and Tran can then negotiate the repayment of the Gross amount of the overpayment"}, {"id": "D", "text": "Un-finalise the prior FY for Tran, reverse both the gross bonus amount and the tax withheld and re-finalise the employee. The employer and Tran can then negotiate the repayment of the Net amount of the overpayment"}]', '{"choice_id": "C"}', 'Per ATO guidance, an overpayment identified in a later financial year requires the prior year to be un-finalised, the gross amount reversed and the employee re-finalised, but the PAYG withheld cannot be adjusted because it was remitted for that year; the employee therefore repays the gross overpayment and claims any tax adjustment via their own return.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a7bbc5f8-ef6e-4398-95ec-d95b77eb8b5f', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Under the Fair Work Act and regulations, employers have to keep their employee records for:', '[{"id": "A", "text": "5 years"}, {"id": "B", "text": "7 years"}, {"id": "C", "text": "For the employees’ full employment period plus 7 years after termination"}, {"id": "D", "text": "Forever"}]', '{"choice_id": "B"}', 'The Fair Work Act 2009 and Fair Work Regulations require employers to keep employee records for a minimum of 7 years.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('88898911-5568-48ca-9d0e-1084cd04a701', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Employers do not need to contribute superannuation for:', '[{"id": "A", "text": "Not applicable, superannuation has to be paid for everyone"}, {"id": "B", "text": "Employees over the age of 70"}, {"id": "C", "text": "Employees under the age of 18 who work less than 30 hours a week and employees over the age of 70"}, {"id": "D", "text": "Employees under the age of 18 who work less than 30 hours a week"}]', '{"choice_id": "D"}', 'Under the SG rules, workers under 18 must work more than 30 hours in a week to be entitled to super, so those working fewer hours are excluded; the upper age limit (70) was removed, meaning super is payable regardless of age.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c46d2321-64c2-4dcd-acca-ce2f88ac9398', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Employers must keep superannuation records for:', '[{"id": "A", "text": "5 years"}, {"id": "B", "text": "7 years"}, {"id": "C", "text": "For the employees’ full employment period plus 7 years after termination"}, {"id": "D", "text": "Forever"}]', '{"choice_id": "A"}', 'Under the Superannuation Guarantee (Administration) Act and ATO requirements, employers must retain super records, including SG contribution details, for a minimum of 5 years. Fair Work Regulations similarly require employee records to be kept for 5 years.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('50dd9e6c-5a68-4122-a375-c39b68a84b79', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'An employer needs to make a stapled super fund request for a new employee when:', '[{"id": "A", "text": "The employee chooses the employers default fund"}, {"id": "B", "text": "The employee does not choose a super fund"}, {"id": "C", "text": "For all new employees"}, {"id": "D", "text": "Never"}]', '{"choice_id": "B"}', 'Under the ATO''s choice of super fund rules (effective 1 November 2021), if a new employee doesn''t nominate a fund, the employer must request their existing ''stapled'' fund from the ATO before defaulting them into the employer''s default fund.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e5ad7537-7238-4fdc-aaa2-ebf36797ea94', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'When an employee enters into a superannuation salary sacrifice arrangement with their employer, the employer must calculate the minimum superannuation guarantee contribution on:', '[{"id": "A", "text": "The employees’ gross salary and wages"}, {"id": "B", "text": "The employees’ OTE, less the salary sacrifice contribution, up to the maximum superannuation contribution base"}, {"id": "C", "text": "The employees’ full OTE"}, {"id": "D", "text": "The employees’ full OTE, up the maximum superannuation contribution base"}]', '{"choice_id": "D"}', 'Since 1 January 2020, salary sacrificed amounts cannot reduce an employer''s OTE base for SG purposes, so the minimum SG is calculated on the employee''s full OTE (including the sacrificed amount), capped at the maximum superannuation contribution base each quarter.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4a1241e4-627b-4bce-b8ee-b9689a091926', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Happy Smiles Pty Ltd has terminated Donald during probation and is making a payment in lieu of notice. The value of the payment in lieu of notice must be:', '[{"id": "A", "text": "Paid on the employees base hourly rate"}, {"id": "B", "text": "Paid on the employees base hourly rate plus a 20% loading"}, {"id": "C", "text": "Paid at the rate the employee would have received had they worked the notice period, including penalty rates, allowances, overtime etc"}, {"id": "D", "text": "Not paid at all"}]', '{"choice_id": "C"}', 'Under the Fair Work Act (s117) and NES, payment in lieu of notice must equal the full amount the employee would have earned over the notice period at their full rate of pay, including penalty rates, allowances, loadings, overtime and any bonuses.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e5134990-4a99-44d9-b1b0-b1cddd02c815', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Tiger Ltd has terminated a casual employee due to poor performance. The casual employee has been employed by Tiger Ltd for 6.5 years and is 30 years old. How much notice is the employee entitled to?', '[{"id": "A", "text": "4 weeks"}, {"id": "B", "text": "5 weeks"}, {"id": "C", "text": "11 weeks"}, {"id": "D", "text": "None"}]', '{"choice_id": "D"}', 'Under the Fair Work Act''s NES, notice of termination does not apply to casual employees, so a genuine casual is not entitled to any notice period regardless of length of service or age.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-27 10:16:57.748483+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('67540d6b-ca07-4aa0-97b5-ede2eb816f26', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under STP Phase 2, a backpay accrued more than 12 months before the payment date is reported as:', '[{"id": "A", "text": "Gross"}, {"id": "B", "text": "Overtime"}, {"id": "C", "text": "Lump sum E"}, {"id": "D", "text": "Bonus and commission"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a91c3241-9762-4bf1-a010-837fae099e1b', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which of the following is not a National Employment Standard?', '[{"id": "A", "text": "Parental leave of 12 months (with a right to request an additional 12 months)"}, {"id": "B", "text": "Notice of Termination and Redundancy Pay"}, {"id": "C", "text": "The maximum standard working week is 40 hours for full time employees, plus ''reasonable'' additional hours"}, {"id": "D", "text": "The right for new employees to receive the Fair Work Information Statement"}]', '{"choice_id": "C"}', 'Under the Fair Work Act''s National Employment Standards, the maximum weekly hours for full-time employees is 38 hours (plus reasonable additional hours), not 40, so statement C is incorrect.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:16:59.912889+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('dd043574-87e0-4ee4-9075-920e43db9dff', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Which of the following statements is true?', '[{"id": "A", "text": "Under the NES, all employees are entitled to annual leave, personal/carer''s leave, long service leave and public holiday leave."}, {"id": "B", "text": "Casual employees are not entitled to long service leave."}, {"id": "C", "text": "Casual employees are entitled to parental leave."}, {"id": "D", "text": "An employee cannot use all their personal/sick leave as carer''s leave."}]', '{"choice_id": "C"}', 'Under the NES, long-term casual employees (regular and systematic employment for at least 12 months with an expectation of ongoing work) are entitled to unpaid parental leave, making C correct; long service leave is governed by state/territory law rather than the NES, so A and B are false.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:16:59.912889+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('595c4a83-fb9a-4a6b-945b-6338faf049c3', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'A notice period by the employer would be required in which of the following situations:', '[{"id": "A", "text": "Termination of employment for a casual employee."}, {"id": "B", "text": "Dismissal for serious misconduct, fraud or theft."}, {"id": "C", "text": "Resignation by employee."}, {"id": "D", "text": "Redundancy."}]', '{"choice_id": "D"}', 'Under the National Employment Standards (Fair Work Act s117), an employer must give written notice (or pay in lieu) when terminating employment, including for genuine redundancy. Notice is not required for casuals, serious misconduct dismissals, or when the employee resigns.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:16:59.912889+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5ebb41e2-fe55-4039-9216-01adc00703ad', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'An employer required to lodge Payroll Tax returns should lodge them:', '[{"id": "A", "text": "Once a year."}, {"id": "B", "text": "Monthly and annually."}, {"id": "C", "text": "Not on the months that are nil."}, {"id": "D", "text": "Quarterly."}]', '{"choice_id": "B"}', 'Payroll tax is a state/territory-based tax that requires monthly returns throughout the year, followed by an annual reconciliation return, so both monthly and annual lodgements are needed.', 1.0, 'human', 'retired', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-30 09:49:21.679406+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1126797d-52fb-427f-82aa-d2e7bc3a4dea', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'The ETP Cap for the financial year 2023-24 is:', '[{"id": "A", "text": "$180,000"}, {"id": "B", "text": "$225,000"}, {"id": "C", "text": "$230,000"}, {"id": "D", "text": "$235,000"}]', '{"choice_id": "D"}', 'The ATO indexed the ETP cap to $235,000 for the 2023-24 financial year; amounts up to this cap are taxed at concessional rates while the excess is taxed at the top marginal rate.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:52.778533+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('7b3b193b-a99d-44b3-9819-736fab82c1f5', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'An employers’ obligation to contribution superannuation is limited to the maximum superannuation contribution base per quarter. The quarterly maximum superannuation contribution base for 2023 -24 is', '[{"id": "A", "text": "$62,270"}, {"id": "B", "text": "$60,220"}, {"id": "C", "text": "$249,080"}, {"id": "D", "text": "$27,500"}]', '{"choice_id": "A"}', 'The ATO set the maximum super contribution base for the 2023-24 financial year at $62,270 per quarter, above which employers are not required to pay the 11% super guarantee.', 1, 'human', 'retired', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-30 09:59:53.127682+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c0bf4d07-1e86-4ef9-ab64-e882e565298b', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Which of the following statements is true?', '[{"id": "A", "text": "Wages for employees working overseas are not subject to payroll tax."}, {"id": "B", "text": "Leave payments on termination are not subject to payroll tax."}, {"id": "C", "text": "Back payments to employees relating to prior financial years are not subject to payroll tax."}, {"id": "D", "text": "Employers hiring employees through an employment agency are not subject to payroll tax on payments made to the agency."}]', '{"choice_id": "D"}', 'Under an employment agency arrangement, the agency is deemed to be the employer and is responsible for payroll tax on the relevant worker payments. The hiring client is generally not liable on its payment to the agency.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-08-31 01:44:32.646553+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('b32691ef-0e4f-49da-8460-f5c4c823d301', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Lump Sum A on an Income Statement does not reflect:', '[{"id": "A", "text": "Unused long service leave that accrued after 15 August 1978 but before 18 August 1993."}, {"id": "B", "text": "Unused holiday pay and other leave related payments that accrued before 18 August 1993."}, {"id": "C", "text": "Unused long service leave accrued after 17 August 1993 or unused holiday pay and other leave related payments, where the amount was paid in connection with a payment that includes (or consists of) a genuine redundancy payment, an early retirement scheme payment or the invalidity segment of an employment termination payment or superannuation benefit."}, {"id": "D", "text": "Unused leave accrued after 17 August 1993 on resignation."}]', '{"choice_id": "D"}', 'Lump Sum A covers unused LSL and holiday pay accrued in the pre-1993 periods and post-17 August 1993 amounts paid in connection with a genuine redundancy, early retirement or invalidity (options A, B and C). Leave accrued after 17 August 1993 that is paid out on a normal resignation is taxed at marginal rates and reported as normal gross earnings, so it is not reflected in Lump Sum A.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:16:59.912889+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('d3c79d61-3e97-4ae9-8d85-c5e9b8c8075b', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'End of year finalisation through STP should be completed by;', '[{"id": "A", "text": "July 1 each year"}, {"id": "B", "text": "July 21 each year"}, {"id": "C", "text": "August 14 each year"}, {"id": "D", "text": "July 14 each year"}]', '{"choice_id": "D"}', 'Under ATO Single Touch Payroll rules, employers must make the finalisation declaration for the previous financial year by 14 July each year.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:16:59.912889+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('cb9995d9-11c2-48f1-8286-a57c0eab1e15', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Employers would generally offer Superannuation Choice of Fund to:', '[{"id": "A", "text": "Government employees in unfunded public sector super schemes."}, {"id": "B", "text": "Eligible employees who are commencing work with the employer, within 28 days of their start date."}, {"id": "C", "text": "Employees who remain a member of a defined benefit fund that is in surplus or who have accrued their maximum benefit."}, {"id": "D", "text": "Employees covered by a range of employment agreements that specify a super fund."}]', '{"choice_id": "B"}', 'Under the ATO Superannuation (Choice of Fund) rules, employers must give eligible new employees a Standard Choice Form (or direct them to complete via ATO online) within 28 days of their start date so they can nominate their fund. Options A, C and D describe categories where choice generally does not apply.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('abd4bef5-c028-449e-985a-50abed7a7354', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'If an Employee does not provide their superannuation fund, you must:', '[{"id": "A", "text": "Pay their super contributions into the companies nominated default fund."}, {"id": "B", "text": "Withhold super contributions until the employee provides their fund details."}, {"id": "C", "text": "Request their stapled super fund details from the ATO and pay into that fund if one exists; if not, pay into the companies nominated default fund."}, {"id": "D", "text": "Pay their super contributions directly to the Australian Taxation Office (ATO) as a holding account."}]', '{"choice_id": "C"}', 'Since the ''stapled super fund'' rules commenced on 1 November 2021, employers must request a new employee''s stapled fund details from the ATO where no choice is made, and only use the employer''s default fund if the ATO confirms no stapled fund exists.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('976f4345-533c-4b12-a976-a9d5230c8a77', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Payroll tax rates and thresholds:', '[{"id": "A", "text": "Vary between States and Territories."}, {"id": "B", "text": "Are indexed in line with Average Weekly Earnings."}, {"id": "C", "text": "Increase proportionately with salaries and wages."}, {"id": "D", "text": "Are set by the Federal Government."}]', '{"choice_id": "A"}', 'Payroll tax is a state/territory tax, so each jurisdiction sets its own rates and thresholds, which differ across Australia.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('ad8e4f22-7942-40c2-bfc7-a00301f21c5c', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'A "daily or weekly hire" arrangement, common in Building & Construction and Plumbing, typically includes:', '[{"id": "A", "text": "A \"follow the job\" loading and 1 day''s notice either way"}, {"id": "B", "text": "No entitlement to sick leave"}, {"id": "C", "text": "A minimum 12 month fixed term"}, {"id": "D", "text": "Exemption from award coverage entirely"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('029e3917-6143-4920-b859-2dafe0aad506', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The superannuation guarantee rate effective 1 July 2025 is:', '[{"id": "A", "text": "9.5%"}, {"id": "B", "text": "12%"}, {"id": "C", "text": "10.5%"}, {"id": "D", "text": "11.5%"}]', '{"choice_id": "B"}', 'Under the Superannuation Guarantee (Administration) Act, the SG rate increased in annual steps and reached its final rate of 12% on 1 July 2025.', 1.0, 'human', 'retired', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-30 09:59:53.271891+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c6035615-c0e2-402f-8a3e-3038fc0b494e', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Which of the following payments are not ''Ordinary Time Earnings'' according to SGR2009/2', '[{"id": "A", "text": "Afternoon and Night Shift penalty rates"}, {"id": "B", "text": "Commission payments"}, {"id": "C", "text": "Overtime"}, {"id": "D", "text": "Christmas bonus"}]', '{"choice_id": "C"}', 'Under SGR 2009/2, overtime is remuneration for work performed outside ordinary hours of work and is therefore excluded from Ordinary Time Earnings, whereas shift penalties, commissions and bonuses generally form part of OTE.', 1.0, 'human', 'retired', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-30 09:59:53.50011+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('78cc448c-4049-4a7a-8aa4-c12af62be6d6', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Which of the following are Reportable Employer Superannuation Contributions (RESC)?', '[{"id": "A", "text": "Contributions in excess of 12%"}, {"id": "B", "text": "Matching employer contributions under an Enterprise Agreement"}, {"id": "C", "text": "Contributions made by an employer that exceed mandated levels and which the employee can influence"}, {"id": "D", "text": "After tax (voluntary) superannuation contributions"}]', '{"choice_id": "C"}', 'RESC are extra super contributions above the compulsory Super Guarantee (or award/agreement mandated) amount that the employee has the capacity to influence, such as salary sacrifice arrangements. After-tax voluntary contributions and simple SG or agreement-mandated amounts the employee can''t influence are not RESC.', 1.0, 'human', 'retired', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-30 09:59:53.64733+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('550ab783-0ffa-4dc0-9a99-22aa8611d2d9', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Which of the following statements regarding Public Holidays is correct?', '[{"id": "A", "text": "Public Holidays are the same in every jurisdiction."}, {"id": "B", "text": "Employees cannot refuse to work on a Public Holiday."}, {"id": "C", "text": "Public Holidays cannot be substituted for other days."}, {"id": "D", "text": "Employees aren''t entitled to be paid for public holidays if they are on unpaid leave on both sides of a public holiday."}]', '{"choice_id": "D"}', 'Under the NES (Fair Work Act), payment for a public holiday only applies if it falls on a day the employee would ordinarily work and be paid; an employee absent on unpaid leave either side of the holiday is not being paid for those days, so no public holiday payment applies. The other options are incorrect as employees can reasonably refuse to work public holidays and holidays can be substituted by agreement.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9bd339b9-c75d-44e9-9ae0-0b576003ed5d', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'STP is mandatory for:', '[{"id": "A", "text": "Employers with a headcount of more than 4 employees"}, {"id": "B", "text": "Employees with a MyGov account"}, {"id": "C", "text": "All employers"}, {"id": "D", "text": "Contractor payments"}]', '{"choice_id": "C"}', 'Single Touch Payroll became mandatory for all employers from 1 July 2019, when the ATO extended the reporting requirement from larger employers (20+) to small employers with 19 or fewer employees.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('483ff000-7b2b-40d0-b729-eab57ca64fb8', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'STP data is remitted to the ATO via:', '[{"id": "A", "text": "The employer’s Business Portal"}, {"id": "B", "text": "The employee’s MyGov account"}, {"id": "C", "text": "STP enabled software"}, {"id": "D", "text": "The Year End empdupe file"}]', '{"choice_id": "C"}', 'Single Touch Payroll requires reporting to be lodged through STP-enabled software (or a registered agent/service using such software) each pay event, rather than portals or the old EMPDUPE file.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f6811eda-7b57-46e7-a72d-90484ad8b595', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which of the following entitlements are not covered by the National Employment Standards?', '[{"id": "A", "text": "Long Service Leave"}, {"id": "B", "text": "Personal/Carer''s Leave"}, {"id": "C", "text": "Workers Compensation"}, {"id": "D", "text": "Annual Leave"}]', '{"choice_id": "C"}', 'Workers compensation is governed by separate state and territory legislation and insurance schemes, not the National Employment Standards. The NES covers minimum entitlements such as annual leave, personal/carer''s leave and, in a transitional sense, long service leave.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c43d415e-4abf-453e-a476-b7e79cf541ac', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which one of the following statements is correct?', '[{"id": "A", "text": "Modern awards do not cover federal government or local government employees."}, {"id": "B", "text": "Transitional arrangements mean that the rates of pay in most modern awards are introduced in four stages from July 2010 to July 2018."}, {"id": "C", "text": "The rate of pay for an employee under an enterprise agreement cannot be less than the relevant rate of pay under the modern award that would apply to the employee or under a national minimum wage order."}, {"id": "D", "text": "An employee does not have to be attached to an award if they are paid the national minimum wage."}]', '{"choice_id": "C"}', 'Under the Fair Work Act, enterprise agreements must meet the Better Off Overall Test and cannot set base rates below the applicable modern award rate or the national minimum wage order.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f5945bf1-27e8-42d4-a045-a1b48d89c38b', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Payroll Tax is payable on:', '[{"id": "A", "text": "All salaries and wages paid to employees and contractors working in Australia only."}, {"id": "B", "text": "All salaries and wages paid to employees and relevant contractors that exceed the exemption threshold."}, {"id": "C", "text": "All organisations including Public Benevolent Institutions, public or non-profit hospitals and charitable organisations."}, {"id": "D", "text": "All salaries and wages paid but not including amounts forgone under an effective salary sacrifice arrangement."}]', '{"choice_id": "B"}', 'Payroll tax is a state/territory tax levied on total taxable wages (including certain contractor payments and superannuation) only when they exceed the relevant annual exemption threshold; below the threshold no payroll tax is payable.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6e761953-6d96-4c61-b174-2e974b61297a', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Payroll Tax harmonisation refers to:', '[{"id": "A", "text": "The exclusion of certain payments from the definition of ''salaries and wages''."}, {"id": "B", "text": "The aligning of legislative provisions across Australian States and Territories."}, {"id": "C", "text": "The setting of uniform payroll tax rates and thresholds across all States and Territories."}, {"id": "D", "text": "The restriction placed on information sharing between State and Revenue offices."}]', '{"choice_id": "B"}', 'Payroll tax harmonisation is the process of aligning the legislative provisions and administration of payroll tax across the states and territories to create consistency; it did not set uniform rates or thresholds, which still differ between jurisdictions.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6bb12489-3c69-4da3-a4d9-f85b0ead76c7', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under an averaging arrangement for ordinary hours, whether overtime applies should be assessed by looking at:', '[{"id": "A", "text": "Any single day''s hours in isolation"}, {"id": "B", "text": "The total hours worked across the whole averaging cycle"}, {"id": "C", "text": "Only the final week of the cycle"}, {"id": "D", "text": "The employee''s historical average from the previous year"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0b95251c-895a-4efb-8616-132e36578a9a', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'An employee’s Whole of Income Cap for 2025-26 is calculated using which figure?', '[{"id": "A", "text": "$245,000"}, {"id": "B", "text": "$180,000"}, {"id": "C", "text": "$185,000"}, {"id": "D", "text": "$235,000"}]', '{"choice_id": "B"}', 'The whole-of-income cap is a fixed $180,000, reduced by other taxable income the employee earns in the income year to determine the amount of an ETP taxed at concessional rates. Amounts above the remaining cap are taxed at the top marginal rate.', 1.0, 'human', 'retired', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-30 09:59:54.025865+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c680039a-f7c0-4ec0-a0b0-e8ba0100403b', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Which of the following payments are not subject to Payroll Tax in any jurisdiction?', '[{"id": "A", "text": "Salary sacrifice superannuation contributions."}, {"id": "B", "text": "Long service leave payments."}, {"id": "C", "text": "Reimbursement of expenses."}, {"id": "D", "text": "Redundancy payments in excess of the tax free portion."}]', '{"choice_id": "C"}', 'Genuine reimbursements of business expenses (where the employee is repaid a precise amount already spent on behalf of the employer) are not treated as wages and are exempt from payroll tax across all Australian jurisdictions, unlike allowances or the other listed payments which are taxable wages.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9885b00c-a875-4861-9456-f5a192a6d09b', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'An employee may cash out annual leave only if:', '[{"id": "A", "text": "An award or agreement permits the practice or the employee is award free."}, {"id": "B", "text": "The employee has completed five years service."}, {"id": "C", "text": "The employee has an entitlement in excess of eight weeks."}, {"id": "D", "text": "When both parties agree to it at any amount."}]', '{"choice_id": "A"}', 'Under the Fair Work Act and NES, cashing out annual leave is only permitted where an applicable modern award or enterprise agreement authorises it, or for award/agreement-free employees by written agreement, with the safeguard that at least 4 weeks'' leave remains after cashing out.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('62589430-952c-4890-afee-c05a56253be7', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Which of the following payments are not Employment Termination Payments?', '[{"id": "A", "text": "Payment in lieu of notice"}, {"id": "B", "text": "Ex-gratia payment"}, {"id": "C", "text": "Unused annual and long service leave payments on termination"}, {"id": "D", "text": "Unused personal leave and RDO payments on termination"}]', '{"choice_id": "C"}', 'Unused annual leave and long service leave paid on termination are taxed under their own separate lump sum rules (Lump Sum A), not as an Employment Termination Payment. In contrast, payments in lieu of notice and ex-gratia payments generally fall within the ATO''s definition of an ETP.', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('285813f9-8610-4dd9-896a-bde72a22c039', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Which of the following statements is true on terminations?', '[{"id": "A", "text": "Notice can be paid out instead of worked."}, {"id": "B", "text": "Super is not paid on any payments of Notice."}, {"id": "C", "text": "Employees must be paid notice if they are terminated because of Serious misconduct."}, {"id": "D", "text": "All employees employed for a specific period are also entitled to Notice on termination."}]', '{"choice_id": "A"}', 'Under the Fair Work Act NES, an employer may either require the employee to work out the notice period or pay them in lieu of notice at their full rate of pay; the other options are false (super is payable on payment in lieu, no notice is required for serious misconduct, and fixed-term contracts ending at their specified date don''t attract notice).', 1.0, 'human', 'live', NULL, '2026-07-27 09:59:57.416037+00', '2026-07-27 10:17:01.323388+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('cf30eb02-1c75-4a55-82c5-73861f97bf55', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'The "span of ordinary hours" refers to:', '[{"id": "A", "text": "The maximum hours an employee can work in a fortnight"}, {"id": "B", "text": "The daytime window within which a day worker''s hours count as ordinary"}, {"id": "C", "text": "The total annual hours under an annualised salary"}, {"id": "D", "text": "The period during which overtime always applies"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('fea6fe65-4748-4e34-82e5-438524afcf28', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under a Rostered Day Off (RDO) arrangement, an employee commonly works 40 hours but is paid for:', '[{"id": "A", "text": "38 hours, banking the other 2 hours towards a day off"}, {"id": "B", "text": "40 hours, with the extra 2 hours paid as overtime"}, {"id": "C", "text": "35 hours, with the balance forfeited"}, {"id": "D", "text": "40 hours, with no banking of hours at all"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('7ebc7e12-1785-4670-a7d9-05d5b4096a17', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Time off in lieu (TOIL) that is not used within 6 months must be:', '[{"id": "A", "text": "Forfeited entirely"}, {"id": "B", "text": "Paid out"}, {"id": "C", "text": "Automatically converted to annual leave"}, {"id": "D", "text": "Extended for a further 12 months without agreement"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('00d82913-80cb-4c6a-a7ab-07be7d459036', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under the "substitution" method of calculating casual overtime, the casual loading is:', '[{"id": "A", "text": "Added on top of the overtime rate"}, {"id": "B", "text": "Dropped entirely, with overtime calculated on the base rate only"}, {"id": "C", "text": "Averaged over the pay period"}, {"id": "D", "text": "Doubled during overtime hours"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('37d11203-f122-4cbc-a32e-b44421ec5c6a', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Applying the "compound" casual overtime method to an award that actually requires "substitution" would most likely result in:', '[{"id": "A", "text": "The casual being correctly paid"}, {"id": "B", "text": "The casual being underpaid"}, {"id": "C", "text": "The casual being overpaid"}, {"id": "D", "text": "No difference to the amount paid"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('361b4c97-c537-4877-b325-8c5a77860ab7', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The guide''s "golden rule" on stacking shift and public holiday penalties is:', '[{"id": "A", "text": "Always add every applicable penalty together"}, {"id": "B", "text": "Pay whichever single penalty is more generous, never both added together"}, {"id": "C", "text": "Always pay the public holiday rate regardless of other penalties"}, {"id": "D", "text": "Alternate between penalties each pay period"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('599f3827-aca5-42da-81bb-1271257319db', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Public holiday penalty rates generally apply to:', '[{"id": "A", "text": "An entire overnight shift that merely touches the public holiday"}, {"id": "B", "text": "Only the hours actually worked on the public holiday itself, unless the award says otherwise"}, {"id": "C", "text": "The full week containing the public holiday"}, {"id": "D", "text": "Only employees rostered exclusively on public holidays"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('bcda2f57-bf37-40bb-a7bb-ca5cdc5fbb89', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'A broken or split shift is best described as:', '[{"id": "A", "text": "Two completely separate shifts on different awards"}, {"id": "B", "text": "Legally one shift worked in two blocks, subject to a capped gap and total span"}, {"id": "C", "text": "A shift that is always unpaid between blocks"}, {"id": "D", "text": "A shift type permitted under every award, including Retail"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('15f7f83d-3c97-43a5-bc19-c9ff80eccc16', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Directing an employee to work through a scheduled unpaid meal break commonly triggers:', '[{"id": "A", "text": "No penalty, since meal breaks are unpaid anyway"}, {"id": "B", "text": "A penalty of 150% to 200% of the ordinary rate for every hour until released"}, {"id": "C", "text": "Automatic termination of the meal break policy"}, {"id": "D", "text": "A penalty only if the employee formally objects in writing"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1e2018d5-9bd2-4d91-aa74-e633ca840245', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Changing a roster generally requires, in order:', '[{"id": "A", "text": "Consultation first, then the award''s specific notice period, unless both parties agree to a swap"}, {"id": "B", "text": "Immediate implementation with notice given afterward"}, {"id": "C", "text": "Union approval before any consultation"}, {"id": "D", "text": "A minimum 30 days'' notice under every award"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('63b930db-58ad-47f9-8cf4-0115eaee8f74', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Allowances that compensate for a duty or working condition, such as first aid or confined space work, are best described as:', '[{"id": "A", "text": "Expense related allowances"}, {"id": "B", "text": "Wage related allowances"}, {"id": "C", "text": "Reimbursements"}, {"id": "D", "text": "Fringe benefits"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('dc89f714-0314-497e-b199-77ff31a7d189', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A payment "dressed up" as an allowance with no genuine connection to an expense the employee actually incurs is treated as:', '[{"id": "A", "text": "A tax free reimbursement"}, {"id": "B", "text": "Ordinary, fully taxable income"}, {"id": "C", "text": "A reportable fringe benefit only"}, {"id": "D", "text": "Exempt from PAYG withholding"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1c54d023-8958-4cda-94a8-824daed29080', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', '"All purpose" allowances are:', '[{"id": "A", "text": "Excluded from superannuation entirely"}, {"id": "B", "text": "Folded into the base rate for overtime, penalties and leave"}, {"id": "C", "text": "Only paid to casual employees"}, {"id": "D", "text": "Never reported separately in STP"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4302fcdb-8d8b-49c4-a4b3-0db544a7ac3a', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'To qualify for a 5th week of annual leave as a shift worker under many awards, an employee generally must:', '[{"id": "A", "text": "Simply work occasional weekend shifts"}, {"id": "B", "text": "Be regularly rostered on Sundays and public holidays as part of a continuous 24/7 roster cycle"}, {"id": "C", "text": "Have more than 10 years of service"}, {"id": "D", "text": "Request it in writing once a year"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9ff93e1f-b6e1-4ca2-8c95-39567840702b', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'When comparing annual leave loading against an applicable penalty rate, the guide says to compare:', '[{"id": "A", "text": "Day by day, paying whichever is greater each day"}, {"id": "B", "text": "Over the whole period of leave being taken, paying whichever is greater, never both"}, {"id": "C", "text": "Always pay both amounts in full"}, {"id": "D", "text": "Only the loading applies, regardless of penalty rates"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6fbc7a40-ca2c-4073-873f-96c62cb4f0f7', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Employers can generally direct an employee to take annual leave for a shutdown or genuine excessive accrual, but directed leave must:', '[{"id": "A", "text": "Reduce the balance below 6 weeks if necessary"}, {"id": "B", "text": "Be a minimum 1 week in whole week blocks, never reducing the balance below 6 weeks"}, {"id": "C", "text": "Always be at least 4 weeks in one block"}, {"id": "D", "text": "Never require any minimum block size"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('67a883c9-b7ee-4e3e-a0b0-100034af7f89', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Cashing out annual leave is capped at:', '[{"id": "A", "text": "1 week per 12-month rolling period"}, {"id": "B", "text": "2 weeks per 12-month rolling period, with the employee retaining at least 4 weeks afterward"}, {"id": "C", "text": "4 weeks per 12-month rolling period"}, {"id": "D", "text": "Unlimited, provided the employee agrees in writing"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2b24c94d-3ec4-4012-800b-f3348a0d195a', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'A "leave in advance" arrangement, where leave is paid before it is accrued, requires:', '[{"id": "A", "text": "No documentation, since it is a common informal practice"}, {"id": "B", "text": "A written agreement for that specific advance, not a blanket approval"}, {"id": "C", "text": "Automatic recovery from the final pay regardless of any agreement"}, {"id": "D", "text": "Union sign-off in every case"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2c4930e5-bbbc-4ff1-961b-dd51fc3595d3', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Compassionate/bereavement leave under the NES applies:', '[{"id": "A", "text": "Once per calendar year regardless of circumstances"}, {"id": "B", "text": "Per qualifying occasion, not limited to once a year"}, {"id": "C", "text": "Only to blood relatives, never household members"}, {"id": "D", "text": "Only where the employee has more than 12 months'' service"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e078c24b-7387-4de3-ac8d-3aad2bead4d4', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'A Keeping in Touch (KIT) day taken during unpaid parental leave is paid as:', '[{"id": "A", "text": "Unpaid leave"}, {"id": "B", "text": "Ordinary hours for that specific day"}, {"id": "C", "text": "A pro-rata redundancy payment"}, {"id": "D", "text": "An ETP"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('d1babd5e-90cb-404f-a507-7f2730f9365f', '6b3da756-e770-49ce-85df-b1eb0278ad54', 'payroll', 'medium', 'Under the NSW Long Service Leave Act 1955, the standard full entitlement is:', '[{"id": "A", "text": "6.0667 weeks per 7 years"}, {"id": "B", "text": "8.6667 weeks per 10 years, plus 4.3333 weeks per subsequent 5 years"}, {"id": "C", "text": "13 weeks per 10 years"}, {"id": "D", "text": "10 weeks per 10 years"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e1b06535-db23-416a-9683-f6db4ffd4095', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'A break in employment can still be forgiven for long service leave continuity purposes if the employee is rehired within the state''s specific window. In NSW, WA, SA, NT and ACT, that window is:', '[{"id": "A", "text": "1 month"}, {"id": "B", "text": "2 months"}, {"id": "C", "text": "3 months"}, {"id": "D", "text": "12 weeks"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('fd8f4174-5805-4c6f-b345-babebeb15cba', 'a2be1770-b669-41c8-a2d1-8631c9aa9ecb', 'payroll', 'medium', 'In Queensland, which reason for leaving generally does NOT unlock early pro rata long service leave access at the 7 year threshold?', '[{"id": "A", "text": "Illness or incapacity"}, {"id": "B", "text": "Domestic or pressing necessity"}, {"id": "C", "text": "Termination for conduct, capacity or performance"}, {"id": "D", "text": "Death of the employee"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('91f60cb7-d519-4805-b2c4-d4abe0f04d52', '7432a898-2096-4c69-bc5c-a69f73461b91', 'payroll', 'medium', 'In Western Australia, cashing out long service leave while still employed:', '[{"id": "A", "text": "Is never permitted under any circumstances"}, {"id": "B", "text": "Is possible by written agreement once minimum qualifying service is reached"}, {"id": "C", "text": "Requires QIRC approval on hardship grounds"}, {"id": "D", "text": "Is automatic after 10 years of service"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('d13e91da-ac74-41f9-8985-440adf5580b0', 'c5b25acd-e123-4595-85a9-b38d12b119b9', 'payroll', 'medium', 'In South Australia, a public holiday that falls during a period of long service leave is treated as:', '[{"id": "A", "text": "Exclusive, paid in addition and not counted as a day of leave taken"}, {"id": "B", "text": "Inclusive, counting as a day of LSL taken, the exception among the states"}, {"id": "C", "text": "Ignored entirely, with no payment"}, {"id": "D", "text": "Automatically extending the LSL period by one day"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('51140d2c-1ba6-46dc-9283-ee8be8397ced', '7432a898-2096-4c69-bc5c-a69f73461b91', 'payroll', 'medium', 'In Western Australia, an employer''s ability to direct when LSL is taken is:', '[{"id": "A", "text": "Unlimited, provided reasonable notice is given"}, {"id": "B", "text": "The employer cannot unilaterally direct an employee to take LSL at a particular time at all"}, {"id": "C", "text": "Limited to shutdown periods only"}, {"id": "D", "text": "The same as the annual leave direction rules"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('39bd6eea-1f64-487d-b6c6-4c3169a4ee23', 'a2be1770-b669-41c8-a2d1-8631c9aa9ecb', 'payroll', 'medium', 'Under the Queensland Court of Appeal decision in Infosys Technologies Ltd v Fox [2025], an employee can qualify for Queensland long service leave after 10 years of continuous service that is:', '[{"id": "A", "text": "Performed entirely within Queensland"}, {"id": "B", "text": "Partly in and partly outside Queensland, with no requirement for substantial connection to the state"}, {"id": "C", "text": "At least 50% performed in Queensland"}, {"id": "D", "text": "Only recognised if the employer is headquartered in Queensland"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a890943b-a1e3-42bc-95e2-b44aa6988b57', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'Transfer of a business as a going concern generally:', '[{"id": "A", "text": "Triggers an immediate LSL payout to the employee"}, {"id": "B", "text": "Preserves continuity of service with the new employer, with no payout triggered at the transfer point"}, {"id": "C", "text": "Resets the employee''s LSL accrual to zero"}, {"id": "D", "text": "Is treated identically to a termination for LSL purposes"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('db3ff135-d5d1-4cf4-806b-eedc0032aa11', '6b3da756-e770-49ce-85df-b1eb0278ad54', 'payroll', 'medium', 'The NSW portable long service leave scheme for community services commenced on 1 July 2025 with a levy rate that:', '[{"id": "A", "text": "Stays fixed at 1.3% indefinitely"}, {"id": "B", "text": "Rises from approximately 1.3% to 1.7% from 1 July 2026"}, {"id": "C", "text": "Is set at a flat 2.2%"}, {"id": "D", "text": "Only applies to employers with more than 100 staff"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('83f8b82d-ae09-4ef5-bc4e-00b1e41e98f2', '207e2bf4-1fb5-48a9-a2eb-e12216c23d94', 'payroll', 'medium', 'Under a portable long service leave scheme, LSL accrued before the scheme''s commencement date is:', '[{"id": "A", "text": "Transferred automatically to the central scheme"}, {"id": "B", "text": "Forfeited entirely"}, {"id": "C", "text": "Remains the individual employer''s liability under the relevant state Act"}, {"id": "D", "text": "Paid out immediately at commencement"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6dd4831c-7d2c-4d00-bacf-38967954b34c', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Termination payments generally fall into three tax groups. Which of the following is NOT one of them?', '[{"id": "A", "text": "Standard (resignation, retirement, dismissal, contract expiry), taxed at marginal rates"}, {"id": "B", "text": "Genuine redundancy and invalidity, which can unlock a tax free portion"}, {"id": "C", "text": "Approved early retirement scheme, taxed the same as genuine redundancy"}, {"id": "D", "text": "Voluntary resignation with a negotiated payout, taxed entirely tax free"}]', '{"choice_id": "D"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('241c4569-2fc2-43cc-8bd9-ce139a524135', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Redundancy pay under the NES scales does not apply at all to:', '[{"id": "A", "text": "Employees with more than 10 years'' service"}, {"id": "B", "text": "Small businesses with fewer than 15 employees"}, {"id": "C", "text": "Employees terminated for serious misconduct"}, {"id": "D", "text": "Casual employees only"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5e794c87-3512-4836-a34d-4e3b9c15c514', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Which termination payment must always attract superannuation, regardless of how the rest of the termination is taxed?', '[{"id": "A", "text": "The tax free portion of a genuine redundancy payment"}, {"id": "B", "text": "Payment in lieu of notice"}, {"id": "C", "text": "Unused long service leave"}, {"id": "D", "text": "An ex-gratia payment"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5be683a5-4547-4870-80e0-8bd97a5bb98a', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'A redundancy is only "genuine" if:', '[{"id": "A", "text": "The employee is redeployed to another role in the same business"}, {"id": "B", "text": "The role itself ends, not just the person in it; if it is backfilled it is not genuine"}, {"id": "C", "text": "The employee agrees in writing to waive their entitlements"}, {"id": "D", "text": "It occurs within the first 12 months of employment"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1ec133eb-48e5-464b-8198-6cd6111596dc', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'For the FY27 genuine redundancy tax free limit (Lump Sum D), the formula is:', '[{"id": "A", "text": "$13,100 base plus $6,552 per completed year of service"}, {"id": "B", "text": "$13,598 base plus $6,801 for each completed year of continuous service"}, {"id": "C", "text": "A flat $180,000 regardless of service"}, {"id": "D", "text": "$270,000 minus year to date earnings"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('b5d9ffea-69e5-472d-ab52-5660ecc76122', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Excluded ETPs (code R), such as genuine redundancy or invalidity payments above the tax free limit, are capped by:', '[{"id": "A", "text": "The ETP cap only"}, {"id": "B", "text": "The whole of income cap only"}, {"id": "C", "text": "Whichever is smaller of the ETP cap and the whole of income cap"}, {"id": "D", "text": "No cap at all"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3c6a3c8e-ef02-4d8e-ae4b-84ea279d671a', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'The whole of income cap, which does not index and starts at $180,000, applies only to:', '[{"id": "A", "text": "Excluded (code R) ETPs"}, {"id": "B", "text": "Non-excluded (code O) ETPs, such as golden handshakes or payment in lieu of notice outside redundancy"}, {"id": "C", "text": "Genuine redundancy payments below the tax free limit"}, {"id": "D", "text": "Unused annual leave paid on termination"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f874cd86-496d-40ea-9abc-dac96de566d4', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'In the seven step marginal rate method for taxing a termination lump sum, HECS/STSL is:', '[{"id": "A", "text": "Deducted at step 3"}, {"id": "B", "text": "Ignored throughout the calculation"}, {"id": "C", "text": "Applied only to the lump sum portion"}, {"id": "D", "text": "Doubled if the employee has an outstanding debt"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('afb13b33-2eb8-49e7-8705-3a722a783b44', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'For the FY27 ETP cap of $270,000, tax on an excluded ETP below the cap for an employee at or over preservation age is generally:', '[{"id": "A", "text": "47% regardless of age"}, {"id": "B", "text": "0.32"}, {"id": "C", "text": "0.17"}, {"id": "D", "text": "Tax free in full"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('036ee9ef-cec2-4aaf-be87-d767ca7c3d68', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under Payday Super from 1 July 2026, superannuation guarantee contributions must reach the employee''s fund within:', '[{"id": "A", "text": "28 days of the end of the quarter"}, {"id": "B", "text": "7 business days of payday"}, {"id": "C", "text": "3 business days of payday"}, {"id": "D", "text": "20 business days of payday"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f4e41039-3cef-4622-b8bb-1bd83f9bea71', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under Payday Super, "Qualifying Earnings" (QE) comprise:', '[{"id": "A", "text": "Only base salary, excluding all allowances"}, {"id": "B", "text": "Ordinary time earnings, salary sacrificed super, and any other amount already included in salary/wages for SG purposes"}, {"id": "C", "text": "Gross wages including overtime and bonuses only"}, {"id": "D", "text": "Only amounts reported through STP Phase 1"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2887506c-4fec-4261-99ba-49e8ebc41f93', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'For the 7 business day Payday Super count, a public holiday observed in only part of a state, such as a regional show day:', '[{"id": "A", "text": "Never counts as a business day"}, {"id": "B", "text": "Still counts as a business day"}, {"id": "C", "text": "Only counts if the employee works that day"}, {"id": "D", "text": "Extends the due date by an extra week automatically"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('75e25929-622e-4002-8d18-69adfeaeda42', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under Payday Super, where a contribution is returned due to changed fund details (e.g. a fund merger), the extended due date is:', '[{"id": "A", "text": "7 business days after payday"}, {"id": "B", "text": "20 business days after payday"}, {"id": "C", "text": "28 days after the quarter ends"}, {"id": "D", "text": "3 business days after payday"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c56113ba-92cc-44d4-b3d6-9dc26ca1eef9', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under Payday Super, a super fund that cannot allocate a received contribution due to missing information must refund it within:', '[{"id": "A", "text": "3 business days"}, {"id": "B", "text": "7 business days"}, {"id": "C", "text": "28 days"}, {"id": "D", "text": "20 business days"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4de61e3a-78e4-4f4b-8117-771f86cb1ba4', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Where an SG Charge remains unpaid 28 days after becoming payable and the ATO issues a written notice, failing to pay within a further 28 days triggers a penalty of:', '[{"id": "A", "text": "10% of the outstanding amount, remittable by the ATO"}, {"id": "B", "text": "25% of the outstanding amount (50% if penalised in the prior 24 months), and this cannot be remitted or waived"}, {"id": "C", "text": "A flat $20 administration fee only"}, {"id": "D", "text": "47% of the outstanding amount"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c1c11a9b-8139-4378-a7dd-30c92c5e71ca', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under Payday Super, the SGC''s administrative uplift replaces the old flat $20 per employee fee with an uplift of up to:', '[{"id": "A", "text": "10% of the shortfall"}, {"id": "B", "text": "25% of the shortfall"}, {"id": "C", "text": "60% of the shortfall, reduced for voluntary disclosure or a clean compliance history"}, {"id": "D", "text": "200% of the shortfall"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('ad1f1bb2-a77b-4a32-aafa-2ce48206cef6', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The ATO Small Business Superannuation Clearing House (SBSCH):', '[{"id": "A", "text": "Remains available indefinitely"}, {"id": "B", "text": "Closes from 1 July 2026 and can no longer be used"}, {"id": "C", "text": "Is being expanded to cover all employer sizes"}, {"id": "D", "text": "Only ever supported self managed super funds"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9f1d7898-5de1-4b5c-aafc-7973a93e3332', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The Paid Parental Leave Superannuation Contribution, applying the SG rate to Government Paid Parental Leave from 1 July 2025, is:', '[{"id": "A", "text": "Calculated and paid by the employer through payroll"}, {"id": "B", "text": "Administered entirely by the ATO and Services Australia, with no payroll role"}, {"id": "C", "text": "Deducted from the employee''s other super contributions"}, {"id": "D", "text": "Only available to employees earning above the high income threshold"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('76d7de21-6165-4cb9-b147-571b025695fe', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Which of the following is generally NOT considered part of Ordinary Time Earnings (superable)?', '[{"id": "A", "text": "Working condition allowances such as crib or danger allowances"}, {"id": "B", "text": "A performance or sign-on bonus"}, {"id": "C", "text": "A deductible allowance, such as for tools or genuine car use"}, {"id": "D", "text": "Paid leave taken during ordinary hours"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f4a18a8a-e1a0-4124-8450-1141ed1dae1b', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'For FY27, the Maximum Contribution Base moves from a quarterly figure to an annual figure of:', '[{"id": "A", "text": "62500"}, {"id": "B", "text": "180000"}, {"id": "C", "text": "270830"}, {"id": "D", "text": "32500"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f3204279-d319-497c-9e06-4fe766ea8bd3', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'A reportable superannuation contribution (RESC) arises when a contribution is both more than 12% of the base and:', '[{"id": "A", "text": "Made through a clearing house"}, {"id": "B", "text": "The employee had individual influence over it, such as a negotiated higher rate or salary sacrifice above 12%"}, {"id": "C", "text": "Paid to a self managed super fund"}, {"id": "D", "text": "Made in the final quarter of the financial year"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('cf065f20-cc0e-494b-b15d-3f8806da6737', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'When an employee works across more than one state in a month, the four tier payroll tax nexus test looks first at:', '[{"id": "A", "text": "Where the employer''s ABN is registered"}, {"id": "B", "text": "The employee''s principal place of residence"}, {"id": "C", "text": "Where wages are actually paid"}, {"id": "D", "text": "Where more than 50% of work is performed"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('dd58bfbc-c7f8-4f41-a3d8-47993f937765', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Under payroll tax grouping provisions, related companies:', '[{"id": "A", "text": "Each get their own separate full threshold"}, {"id": "B", "text": "Share a single threshold, and each becomes liable for the others'' payroll tax"}, {"id": "C", "text": "Are automatically exempt from payroll tax"}, {"id": "D", "text": "Must each register in a different jurisdiction"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('963ec667-95ca-4121-9376-31d02349f674', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'An employee seconded overseas remains liable for payroll tax purposes for:', '[{"id": "A", "text": "The first 6 months, with a refund claimable at reconciliation once they pass 6 continuous months away"}, {"id": "B", "text": "The entire period of the secondment, however long"}, {"id": "C", "text": "No period at all, they are immediately exempt"}, {"id": "D", "text": "12 months, regardless of when they return"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4b6a1a22-ac93-491e-9300-1e691645b4f0', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'From FY27, the Northern Territory applies which payroll tax rate structure?', '[{"id": "A", "text": "A flat 5.5% for all employers, unchanged"}, {"id": "B", "text": "6.5% for employers with Australia-wide wages over $100 million, 5.5% for all other employers"}, {"id": "C", "text": "8.75% for all employers"}, {"id": "D", "text": "A sliding scale from 4% to 6.1%"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
