INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('91caf11c-661f-4651-a2f9-91c376706322', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The test for whether a worker is genuinely an employee or an independent contractor is primarily about:', '[{"id": "A", "text": "The label used in the contract"}, {"id": "B", "text": "Substance: control over how work is done, ability to subcontract, who provides equipment, and genuine independence"}, {"id": "C", "text": "Whether the worker has an ABN"}, {"id": "D", "text": "The length of the engagement only"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
