INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('88524822-6287-4e66-ab2e-0be9e6abb3a5', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'On a Tax File Number declaration, the tax free threshold tick box is significant because:', '[{"id": "A", "text": "Payroll decides which box to tick on the employee''s behalf"}, {"id": "B", "text": "It is the single most consequential field for standard PAYG withholding, and payroll processes the form as completed"}, {"id": "C", "text": "It only affects superannuation, not PAYG"}, {"id": "D", "text": "It can be changed retrospectively without a new declaration"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('176a0863-f792-4c2d-aa46-0d66ee5b2c12', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A backpay that includes amounts relating to an earlier financial year requires:', '[{"id": "A", "text": "The ATO''s specific back payment method, rather than being taxed as if all earned in the current period"}, {"id": "B", "text": "No special treatment, it is simply added to gross pay"}, {"id": "C", "text": "The termination marginal rate method"}, {"id": "D", "text": "To be reported as a fringe benefit"}]', '{"choice_id": "A"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('085c68c9-cf83-4266-90dd-22d68ab0e65a', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Bonuses and commissions relating to work performed over more than one pay period are taxed using a method that:', '[{"id": "A", "text": "Taxes the full amount in the pay run it is actually paid, at marginal rates"}, {"id": "B", "text": "Spreads the amount notionally across the periods it was earned in to estimate correct withholding"}, {"id": "C", "text": "Applies a flat 15% withholding rate"}, {"id": "D", "text": "Defers all tax until the following financial year"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f25f4ad7-21bf-4da0-8a57-f46119d4fee6', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The Protected Earnings Amount, relevant to garnishee orders and child support deduction notices, sets:', '[{"id": "A", "text": "The maximum amount that can ever be deducted from any pay"}, {"id": "B", "text": "A floor below which an employee''s take-home pay cannot fall, with any shortfall carried forward"}, {"id": "C", "text": "A fixed percentage of gross pay that must always be deducted"}, {"id": "D", "text": "The minimum wage rate for the relevant award"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('8d38c2c1-4875-4e70-8de8-b57b177ec79d', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Total Remuneration Package (TRP) is best described as:', '[{"id": "A", "text": "Base salary only, with superannuation paid on top"}, {"id": "B", "text": "Base salary plus superannuation and other benefits, with super coming out of that figure rather than on top"}, {"id": "C", "text": "Wages paid for actual hours worked"}, {"id": "D", "text": "The value of fringe benefits only"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('aea40e0f-e97b-48fa-9c93-743107282049', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A cash car allowance added to salary to cover vehicle running costs is:', '[{"id": "A", "text": "A fringe benefit, subject to FBT"}, {"id": "B", "text": "Taxed at normal marginal rates as ordinary income, with no FBT applying"}, {"id": "C", "text": "Exempt from tax entirely"}, {"id": "D", "text": "Only taxable if it exceeds $10,000 per year"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('ec951f84-a7fb-44bb-9566-8f5287930ee2', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'For a salary sacrifice arrangement to be effective and genuinely reduce assessable income, all of the following conditions must be met EXCEPT:', '[{"id": "A", "text": "The agreement is entered into before the work is performed and income is earned"}, {"id": "B", "text": "There is a clear agreement between employer and employee, usually in writing"}, {"id": "C", "text": "The employee has no ability to access the sacrificed amount as cash"}, {"id": "D", "text": "The arrangement can be applied retrospectively to a bonus already earned"}]', '{"choice_id": "D"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4c88d508-85ec-418a-b4e6-bcef1795e470', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Salary sacrificed superannuation is treated as:', '[{"id": "A", "text": "An after-tax employee contribution"}, {"id": "B", "text": "An employer contribution, taxed inside the fund"}, {"id": "C", "text": "A fringe benefit reportable on the income statement"}, {"id": "D", "text": "Exempt from all taxation"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('16fbc737-c723-4357-955d-afcb62260a14', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'HECS/HELP loan repayments reimbursed by an employer are:', '[{"id": "A", "text": "Reduced to nil under the otherwise deductible rule"}, {"id": "B", "text": "Fully taxable regardless of whether the course was work related"}, {"id": "C", "text": "Exempt in full"}, {"id": "D", "text": "Deemed a fringe benefit"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('8b50c47a-b4a1-4c0d-bbc5-157c46d6d300', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A "novated lease" is best described as:', '[{"id": "A", "text": "A two way arrangement solely between employer and employee"}, {"id": "B", "text": "A three way arrangement between employer, employee and a finance company, where the vehicle reverts to the employee if employment ends"}, {"id": "C", "text": "A government-funded vehicle scheme with no FBT implications"}, {"id": "D", "text": "An arrangement only available for utes and panel vans"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1d86513d-76aa-4684-bd00-ab1efa99f366', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Under the Employee Contribution Method (ECM) on a novated lease, the employee pays part of the running costs from after tax income, specifically calculated to:', '[{"id": "A", "text": "Increase the taxable value of the car fringe benefit"}, {"id": "B", "text": "Reduce the taxable value of the car fringe benefit to nil"}, {"id": "C", "text": "Eliminate the need for a logbook"}, {"id": "D", "text": "Avoid any GST implications for the employer"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0987a5d0-0172-47e5-bab4-61da3c5a83b8', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Which STP submission type confirms to the ATO that all information for an employee has been provided for the financial year, making their income statement tax ready?', '[{"id": "A", "text": "Pay event"}, {"id": "B", "text": "Update event"}, {"id": "C", "text": "Finalisation declaration"}, {"id": "D", "text": "Full file replacement"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0cfc3a96-e2cf-421d-a8a2-e453f6c776bf', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'An "update event" in STP is used to:', '[{"id": "A", "text": "Lodge the mandatory submission on or before every payday"}, {"id": "B", "text": "Correct or adjust previously reported year to date amounts outside of a normal pay event"}, {"id": "C", "text": "Replace an entire lodgement sent in error"}, {"id": "D", "text": "Confirm the financial year''s finalisation"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:51.812643+00', '2026-07-29 04:57:51.812643+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c2ac459c-2920-4b04-ab2a-579ce5749576', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'When a payroll system change transfers employee year to date amounts across using the "zeroing out" method, the employer:', '[{"id": "A", "text": "Submits an update event quoting the previous BMS ID to replace the old income statement"}, {"id": "B", "text": "Lodges an update event setting all amounts to zero in the old system, telling the ATO the old income statement should no longer display"}, {"id": "C", "text": "Takes no action, since the ATO handles the transfer automatically"}, {"id": "D", "text": "Must notify every employee individually by letter"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('02770ac7-e114-436f-8272-8b85b33bb3e7', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'If an employer changes payroll software mid-year and does NOT transfer employee year to date amounts across:', '[{"id": "A", "text": "The ATO must be formally notified in advance"}, {"id": "B", "text": "No ATO notification is required, but the employee will see more than one income statement for the year"}, {"id": "C", "text": "The employee''s prior year to date figures are automatically voided"}, {"id": "D", "text": "A full file replacement must be lodged immediately"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('478b144a-52f8-4641-8747-b707e3d8b33d', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'The STP cessation reason code "R" refers to:', '[{"id": "A", "text": "Resignation or retirement"}, {"id": "B", "text": "Employer initiated termination due to genuine redundancy, approved early retirement scheme, or non-genuine redundancy"}, {"id": "C", "text": "Death of the employee"}, {"id": "D", "text": "Natural end of a fixed term contract"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f42f5eeb-14c3-41c4-96d1-2c85b39437fd', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The TFN substitution code 333333333 is used for:', '[{"id": "A", "text": "An employee who has not provided a TFN at all"}, {"id": "B", "text": "An under 18 employee earning below the tax free threshold"}, {"id": "C", "text": "An employee who has applied for a TFN but not yet received it"}, {"id": "D", "text": "An employee on a qualifying social security or service pension"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('c766e7ea-fb44-4002-ab3f-76f84216e3a9', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'The STP income type "CHP" refers to:', '[{"id": "A", "text": "Working holiday makers"}, {"id": "B", "text": "Closely held payees, for businesses using the concession for 19 or fewer employees"}, {"id": "C", "text": "Contractors under a voluntary agreement"}, {"id": "D", "text": "Foreign employment income for an Australian resident working overseas"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('4a3a6020-e81d-48aa-82c5-3e43376e824c', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under STP Phase 2, ordinary hours, shift penalties, public holiday penalties, and casual loading are all reported under which category?', '[{"id": "A", "text": "Overtime"}, {"id": "B", "text": "Gross"}, {"id": "C", "text": "Other paid leave (type O)"}, {"id": "D", "text": "Lump sum E"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('29d37bca-a75c-4ba0-94a6-ab576e3ecf5c', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Under STP Phase 2, annual leave loading that is demonstrably referable to a lost overtime opportunity is reported as:', '[{"id": "A", "text": "Gross"}, {"id": "B", "text": "Overtime"}, {"id": "C", "text": "Leave type O"}, {"id": "D", "text": "Lump sum A"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('82035316-9032-436f-bcd9-f584cea07ada', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'A Lump Sum E amount spanning more than 10 years in arrears must be reported:', '[{"id": "A", "text": "Split evenly across every year it relates to"}, {"id": "B", "text": "Entirely against the 10th year back, since STP only accepts one year to date value per financial year for up to 10 years"}, {"id": "C", "text": "In the current financial year only"}, {"id": "D", "text": "As an ETP rather than a lump sum"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('32768c30-ec10-40c5-9138-dc88e9ad9118', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Under ETP coding, code "S" applies where:', '[{"id": "A", "text": "It is the very first ETP paid for a termination"}, {"id": "B", "text": "A further code R payment is made in a later income year for the same termination where a code R or O payment was already made"}, {"id": "C", "text": "The payment is for unused sick leave"}, {"id": "D", "text": "The payment relates to a genuine redundancy only"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6e0086d7-818b-490b-856a-52ff925a5b88', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Salary sacrifice amounts in STP are reported as:', '[{"id": "A", "text": "A net, already-reduced gross figure"}, {"id": "B", "text": "Positive amounts, with the pre-sacrifice gross figure reported in full alongside the sacrifice amount"}, {"id": "C", "text": "Negative adjustments to gross pay"}, {"id": "D", "text": "Only visible on the employee''s payslip, never in STP"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('8c1f5821-8d5e-4e08-a1f9-e823992e418c', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'medium', 'Where an employer finds an error in previously reported STP data, it is corrected using:', '[{"id": "A", "text": "A brand new pay event reissuing every prior pay event"}, {"id": "B", "text": "An update event reporting the corrected year to date figures"}, {"id": "C", "text": "A finalisation declaration"}, {"id": "D", "text": "A full file replacement in every case"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('bc7bbf00-6aba-4f25-99fd-347b45964b67', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Under the SCHADS Award sleepover changes from 1 June 2026, employees can now work up to how many ordinary hours by agreement, immediately before and after a sleepover?', '[{"id": "A", "text": "8 hours"}, {"id": "B", "text": "10 hours"}, {"id": "C", "text": "12 hours, capped at 8 on either side"}, {"id": "D", "text": "16 hours"}]', '{"choice_id": "C"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9cc15d48-c7e5-4358-8915-d42a3f64bd1b', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Additional pay periods (53 weekly or 27 fortnightly pays in a financial year) create a risk that:', '[{"id": "A", "text": "Superannuation is overpaid"}, {"id": "B", "text": "Standard PAYG withholding tables under-withhold tax across the year, leaving the employee with a tax bill at return time"}, {"id": "C", "text": "The employer must skip a pay run"}, {"id": "D", "text": "Payroll tax thresholds are automatically breached"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3e29cb8f-ba3a-4932-a485-564f1cacba8e', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'For a child born or adopted from 1 July 2026, the maximum Government Parental Leave Pay increases to:', '[{"id": "A", "text": "24 weeks (120 days)"}, {"id": "B", "text": "26 weeks (130 days)"}, {"id": "C", "text": "20 weeks (100 days)"}, {"id": "D", "text": "30 weeks (150 days)"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('0c79f491-f5be-4c01-be76-50333fce141c', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Under Baby Priya''s Law (from 7 November 2025), an employer generally cannot refuse or cancel an employee''s entitlement to employer funded parental leave where:', '[{"id": "A", "text": "The employee resigns before taking the leave"}, {"id": "B", "text": "A child is stillborn or dies, unless the employee requests cancellation or a narrow exception applies"}, {"id": "C", "text": "The employee has less than 12 months'' service"}, {"id": "D", "text": "The business restructures during the leave period"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a00379e9-4a3d-466f-a27c-a34dace6c05b', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Following the Fair Work Commission decision on junior rates in the Retail, Fast Food and Pharmacy awards, junior rates are being phased out over a transitional period for employees:', '[{"id": "A", "text": "Under 18 with any length of service"}, {"id": "B", "text": "Aged over 18 with at least 6 months'' service, over a 4 year transitional period"}, {"id": "C", "text": "Aged over 21 immediately, with no transition"}, {"id": "D", "text": "Only in the Fast Food Industry Award"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('317deb28-95ef-4f51-9948-1728f0bbf9ac', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The approved cents per kilometre rate is proposed to rise to 91 cents per km, applying tax free to reimbursements up to:', '[{"id": "A", "text": "2,500km per vehicle per year"}, {"id": "B", "text": "5,000km per vehicle per year"}, {"id": "C", "text": "10,000km per vehicle per year"}, {"id": "D", "text": "Unlimited kilometres"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9a7b67c6-2a0b-4991-b3b1-49d3edbbf71b', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'Payroll tax cents per kilometre exemptions typically run how far behind the ATO''s current rate under most state and territory legislation?', '[{"id": "A", "text": "The same year as the current ATO rate"}, {"id": "B", "text": "One year behind the ATO''s current rate"}, {"id": "C", "text": "Two years behind"}, {"id": "D", "text": "They are never linked to the ATO rate"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('26f8d649-63bd-4267-bbdc-78469f302287', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'The Fair Work Commission''s FY27 annual wage review increased the National Minimum Wage by 4.75% to a new weekly rate of:', '[{"id": "A", "text": "978.1"}, {"id": "B", "text": "1004.9"}, {"id": "C", "text": "958.2"}, {"id": "D", "text": "1050"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f2c2037d-5b88-4f52-ba79-28197026dd6e', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A pay period spanning 29 June to 5 July, paid on 9 July, should use:', '[{"id": "A", "text": "The old financial year''s PAYG tables, super rate and Award rate throughout"}, {"id": "B", "text": "The new financial year''s PAYG tables and super rate, but the old Award rate"}, {"id": "C", "text": "The new Award rate but the old PAYG tables"}, {"id": "D", "text": "A blended rate averaged across both financial years"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('40425c51-6eb3-4f48-8bb9-9be57361403f', '6b3da756-e770-49ce-85df-b1eb0278ad54', 'payroll', 'medium', 'The NSW community services portable long service leave scheme''s transitional design means that once an employee takes leave, the employer:', '[{"id": "A", "text": "Has no further involvement, the scheme pays everything"}, {"id": "B", "text": "Pays the employee the full entitlement, then claims reimbursement from the scheme for the portion already funded through levies"}, {"id": "C", "text": "Only pays the pre-scheme portion, with the scheme paying the rest directly"}, {"id": "D", "text": "Is refunded in full for all levies previously paid"}]', '{"choice_id": "B"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e0aac3ed-2b7c-471a-a432-11cad68bed5f', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'A well drafted employment contract should, at minimum, address all of the following EXCEPT:', '[{"id": "A", "text": "Wages or salary, and award coverage or the basis for none"}, {"id": "B", "text": "Notice of termination and hours of work"}, {"id": "C", "text": "Confidential information, intellectual property and any probation period"}, {"id": "D", "text": "The employee''s personal banking PIN and passwords"}]', '{"choice_id": "D"}', NULL, 1, 'human', 'live', NULL, '2026-07-29 04:57:52.094652+00', '2026-07-29 04:57:52.094652+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('977898a8-25b0-4468-9078-759d7b2dc926', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Monica has used all of her paid sick (personal)/carer''s leave. Monica calls her boss Pete to let him know that she needs to take a day off to care for her sick son. What should Pete say?', '[{"id": "A", "text": "Monica must use her annual leave."}, {"id": "B", "text": "Monica can take unpaid carer''s leave."}, {"id": "C", "text": "If Monica doesn''t come to work, Pete has a valid reason to terminate her employment."}, {"id": "D", "text": "The employee can use compassionate leave"}]', '{"choice_id": "B"}', 'Under the NES, once an employee has exhausted their paid personal/carer''s leave, they are entitled to unpaid carer''s leave per occasion to care for a member of their immediate family or household.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-07-29 04:57:52.357984+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('952d635a-2bb1-485f-9c3f-5031512d7985', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'easy', 'In the video''s example, a casual employee works 25 hours in a week at a casual rate of $28.90 per hour. What is the amount they are paid for that week, and how is it described?', '[{"id": "A", "text": "$722.50 gross pay before tax"}, {"id": "B", "text": "$722.50 net pay after tax"}, {"id": "C", "text": "$705.00 gross pay before tax"}, {"id": "D", "text": "$867.00 net pay after tax"}]', '{"choice_id": "A"}', 'The video calculates 25 hours × $28.90 = $722.50 and states this is the employee''s gross pay before tax.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:42.728386+00', '2026-07-30 08:18:42.728386+00', 'c418f6ec-acb7-4bbf-a0a1-757f09b81760', '9105c54ae4178192ee05007e373fc1b38d943553bd014d8226af4840a53edd6b');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('72da0a53-7b37-4a45-a21e-198c34f9ff2e', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'easy', 'According to the video, what does it mean when an employee on an annual salary is paid on "auto pay"?', '[{"id": "A", "text": "They are paid only for the hours they actually work each pay period"}, {"id": "B", "text": "They receive the same salary amount each pay"}, {"id": "C", "text": "Their pay is automatically calculated from their timesheet each pay period"}, {"id": "D", "text": "Their salary is automatically increased each year"}]', '{"choice_id": "B"}', 'The video explains that auto pay means the salaried employee receives the same salary each pay.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:42.728386+00', '2026-07-30 08:18:42.728386+00', 'c418f6ec-acb7-4bbf-a0a1-757f09b81760', '9105c54ae4178192ee05007e373fc1b38d943553bd014d8226af4840a53edd6b');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('99f932e3-d90d-4dc9-ad4c-9b0e1321eb7a', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'In the video''s example, an employee on an annual salary of $85,000 is paid fortnightly. What amount do they receive each fortnight?', '[{"id": "A", "text": "$1,634.62"}, {"id": "B", "text": "$3,269.23"}, {"id": "C", "text": "$3,541.67"}, {"id": "D", "text": "$6,538.46"}]', '{"choice_id": "B"}', 'The video states that an employee on an annual salary of $85,000 on a fortnightly pay cycle receives $3,269.23 each fortnight.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:42.728386+00', '2026-07-30 08:18:42.728386+00', 'c418f6ec-acb7-4bbf-a0a1-757f09b81760', '9105c54ae4178192ee05007e373fc1b38d943553bd014d8226af4840a53edd6b');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('63ba8ad1-9223-4ada-bc6f-582eafee7087', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'For an employee paid on auto pay, when does the video say the employer will amend the pay?', '[{"id": "A", "text": "Only at the end of each financial year"}, {"id": "B", "text": "Every pay period, based on the hours actually worked"}, {"id": "C", "text": "Only when there are adjustments, such as leave taken"}, {"id": "D", "text": "Only when the employee requests a review of their pay"}]', '{"choice_id": "C"}', 'The video states the employer will only amend the pay if there are adjustments, such as leave taken.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:42.728386+00', '2026-07-30 08:18:42.728386+00', 'c418f6ec-acb7-4bbf-a0a1-757f09b81760', '9105c54ae4178192ee05007e373fc1b38d943553bd014d8226af4840a53edd6b');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('81a1ac80-fc4e-4fe6-8e80-2390d25098dd', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'hard', 'Under the general exemptions described in the video, services that are ordinarily needed by the business are exempt if provided for fewer than how many days in the year?', '[{"id": "A", "text": "90 days"}, {"id": "B", "text": "120 days"}, {"id": "C", "text": "180 days"}, {"id": "D", "text": "240 days"}]', '{"choice_id": "C"}', 'The video states that one general exemption applies where the services are ordinarily needed but provided for fewer than 180 days in the year (a separate exemption covers the same kind of service provided on 90 days or fewer).', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:23:25.582945+00', '2026-07-30 08:23:25.582945+00', '038c9571-f221-482d-9540-1813d71e270f', '0965a7cc3a7a550e4e43b4521a83086cb62857523b8f8e9a4d88dc9b0b4771b5');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('35515994-9482-4574-ac1d-1697c5c6dec1', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'According to the video, how much notice of termination must an employer give to a 50-year-old permanent employee with four years of continuous service?', '[{"id": "A", "text": "Two weeks"}, {"id": "B", "text": "Three weeks"}, {"id": "C", "text": "Four weeks"}, {"id": "D", "text": "Five weeks"}]', '{"choice_id": "C"}', 'The video states the employee gets three weeks for service (more than three but not more than five years) plus one extra week because they are over 45 with more than two years'' service, totalling four weeks.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:24:21.489496+00', '2026-07-30 08:24:21.489496+00', '5b92f2f7-1e84-42e3-bd89-d91691645304', '5e4d345e820c35bf23cff489d558367194c1afb016b9a60d47c73f7a901c206e');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e50122ec-b923-4f21-9c62-9ccfc5b5254c', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'Oceans Pty Ltd pays their employees 95 cents per kilometre for business travel as per their award. The ATO reasonable rate is 91 cents. This means:', '[{"id": "A", "text": "Only 91 cents is tax free, and the additional 4 cents is taxable, up to 5,000 business kms in a year"}, {"id": "B", "text": "85 cents is taxable, and the additional 10 cents is tax free, up to 5,000 business kms in a year"}, {"id": "C", "text": "The whole amount is taxable"}, {"id": "D", "text": "The whole amount is tax free, up to 5,000 business kms in a year"}]', '{"choice_id": "A"}', 'Under ATO rules, a car allowance paid on a cents-per-kilometre basis is exempt from PAYG withholding only up to the ATO''s approved reasonable rate (91c) for the first 5,000 business kms; any excess (the extra 4c) is treated as assessable and subject to withholding.', 1, 'human', 'live', NULL, '2026-07-16 21:39:40.977799+00', '2026-08-31 01:44:32.46909+00', NULL, NULL);
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('be1eeb6c-5d05-4460-b3cc-6d19a39786be', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'medium', 'The video says the ATO''s approved cents per kilometre rate is 91 cents this year. If an award requires you to pay 99 cents per kilometre, what is the tax treatment?', '[{"id": "A", "text": "The whole 99 cents is tax free because it is required by the award"}, {"id": "B", "text": "The whole 99 cents is taxed because it exceeds the approved rate"}, {"id": "C", "text": "91 cents is tax free and the extra 8 cents per kilometre is taxed in the normal cycle"}, {"id": "D", "text": "The excess is tax free up to 5,000 kilometres and then the full amount is taxed"}]', '{"choice_id": "C"}', 'The presenter states you withhold nothing up to the reasonable amount (91 cents) and tax only the excess, so the extra 8 cents per kilometre is taxed in the normal cycle, and anything above 5,000 kilometres is also taxed.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:15:54.169071+00', '2026-07-30 08:15:54.169071+00', '20d2f327-fc13-40f4-a729-cc4a734008bc', '2d30316df9057cefb01932b0c6522a348f29723283ecccb866521f4d08e2a592');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('25563d7c-4599-4761-bdff-a268fa339631', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'easy', 'According to the video, how should annual leave in advance be documented?', '[{"id": "A", "text": "With a single blanket approval signed at the start of employment covering all future advances"}, {"id": "B", "text": "Separately for every single instance, recording the amount advanced and the date"}, {"id": "C", "text": "Only where the total advanced exceeds two weeks of leave"}, {"id": "D", "text": "Verbally at the time of the request, with a file note added at the end of the financial year"}]', '{"choice_id": "B"}', 'The video states every single instance of leave in advance should be documented separately " not covered by one broad approval " recording the amount, the date and ideally written agreement from the employee.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:15:56.002547+00', '2026-07-30 08:15:56.002547+00', '09a46ca4-da2b-4e3d-90d9-d0745642a0be', 'e0f10e29e8a1f64f27ebd8d8af6e57eeb537115237adf0d3090c2653e7e30b77');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('45287c7a-84ba-44ec-8867-68dc1935f487', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'The video describes annual leave in advance as "discretionary". What does it mean by this?', '[{"id": "A", "text": "The employer does not have to agree to it, and awards or policies may differ on whether it''s allowed at all"}, {"id": "B", "text": "The employee can choose how much of their future accrual to draw down at any time"}, {"id": "C", "text": "Fair Work decides on a case-by-case basis whether an advance can be granted"}, {"id": "D", "text": "The employer must approve it unless the employee has a negative leave balance already"}]', '{"choice_id": "A"}', 'The video says leave in advance is discretionary " the employer doesn''t have to agree to it " and that different awards or policies may take different views on whether it is permitted.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:15:56.002547+00', '2026-07-30 08:15:56.002547+00', '09a46ca4-da2b-4e3d-90d9-d0745642a0be', 'e0f10e29e8a1f64f27ebd8d8af6e57eeb537115237adf0d3090c2653e7e30b77');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('149f2a14-5322-465b-a130-0530c819ba78', 'd93c3c07-648c-44d5-a6c5-9e1506837b0f', 'payroll', 'medium', 'Per the video, when may an employer be able to recover the value of an unearned leave advance from an employee''s final pay?', '[{"id": "A", "text": "In all cases, because the money was never accrued in the first place"}, {"id": "B", "text": "Only where the employee was terminated rather than resigned"}, {"id": "C", "text": "Only where that recovery has been properly agreed to in advance, in writing"}, {"id": "D", "text": "Only after obtaining written approval from the Fair Work Commission"}]', '{"choice_id": "C"}', 'The video states recovery from final pay may be possible, but only where it has been properly agreed to in advance and in writing.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:15:56.002547+00', '2026-07-30 08:15:56.002547+00', '09a46ca4-da2b-4e3d-90d9-d0745642a0be', 'e0f10e29e8a1f64f27ebd8d8af6e57eeb537115237adf0d3090c2653e7e30b77');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('52c9132d-0b82-46cb-a69d-73b6896a5859', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'easy', 'According to the video, what is the correct formula for calculating back pay owed when a rate increase applies retroactively?', '[{"id": "A", "text": "Hours already worked multiplied by the new rate"}, {"id": "B", "text": "Hours already worked at the old rate multiplied by the difference between the new and old rate"}, {"id": "C", "text": "Hours already worked multiplied by the old rate, less tax already withheld"}, {"id": "D", "text": "The new rate multiplied by the number of pay periods affected"}]', '{"choice_id": "B"}', 'The video states the calculation is the hours already worked at the old rate multiplied by the difference between the new rate and the old rate \is is the top-up owed.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:04.727484+00', '2026-07-30 08:18:04.727484+00', '4e16dd93-7e2d-4e26-b1fd-7811c32386d4', '0857df3aee68e31f556f6d1d620868c5fceb8108e077114fc30f8bce9e7fe314');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('bc8b67d7-94ba-4f9b-806b-0224fe186a0b', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'easy', 'According to the video, how should annual leave in advance be documented?', '[{"id": "A", "text": "With a single blanket approval signed at the start of employment covering all future advances"}, {"id": "B", "text": "Separately for every single instance of leave in advance"}, {"id": "C", "text": "Only when the advance exceeds two weeks of leave"}, {"id": "D", "text": "Verbally, with a file note made by the payroll officer"}]', '{"choice_id": "B"}', 'The video stresses that every single instance of leave in advance should be documented separately, not covered by one broad approval at the start of employment.', 1.0, 'ai', 'live', NULL, '2026-07-30 08:15:47.458541+00', '2026-08-11 06:33:49.955292+00', 'e59618dc-32cb-41dc-a415-7ea128e2b91f', 'e0f10e29e8a1f64f27ebd8d8af6e57eeb537115237adf0d3090c2653e7e30b77');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('86dee715-4e86-409c-8c5b-aaff7af399a0', '708369e1-1a84-4c61-be61-9d1f862e2cc7', 'payroll', 'easy', 'According to the video, how should a shift allowance or first aid allowance be treated?', '[{"id": "A", "text": "Tax free up to a reasonable amount set by the ATO, with only the excess taxed"}, {"id": "B", "text": "Part of earnings, taxed in the normal pay cycle and generally subject to superannuation"}, {"id": "C", "text": "Not taxed at all, but reportable in full at year end"}, {"id": "D", "text": "Taxed at a varied sliding rate depending on the employee''s salary"}]', '{"choice_id": "B"}', 'The video explains that allowances relating to conditions of work, skills or qualifications (shift, first aid, tool, on call) form part of earnings, so they are taxed in the normal pay cycle and are generally superable.', 1.0, 'ai', 'live', NULL, '2026-07-30 08:15:54.169071+00', '2026-08-11 06:34:03.748853+00', '20d2f327-fc13-40f4-a729-cc4a734008bc', '2d30316df9057cefb01932b0c6522a348f29723283ecccb866521f4d08e2a592');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('afbdddb7-8074-4a46-ac9f-4e8c6a142145', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'hard', 'How does the video link leave in advance to the broader deduction rules?', '[{"id": "A", "text": "Deductions from final pay are always lawful where they relate to leave entitlements"}, {"id": "B", "text": "An employer generally cannot deduct from final pay without a legal requirement or the employee''s genuine agreement, and a signed leave-in-advance agreement can support a lawful deduction"}, {"id": "C", "text": "Leave-in-advance recovery is exempt from the deduction rules because it is not really wages"}, {"id": "D", "text": "Deductions for advanced leave can only be made in equal instalments across the final three pay periods"}]', '{"choice_id": "B"}', 'The video explains that deductions generally require a legal requirement or the employee''s genuine agreement, and a leave-in-advance arrangement signed at the time the advance was given is exactly the kind of agreement that can support a lawful deduction later.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:15:56.002547+00', '2026-07-30 08:15:56.002547+00', '09a46ca4-da2b-4e3d-90d9-d0745642a0be', 'e0f10e29e8a1f64f27ebd8d8af6e57eeb537115237adf0d3090c2653e7e30b77');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f2fae06a-f58a-4294-a1cb-0ecbf0421728', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'easy', 'In the video''s example, an employee works 40 hours in one week and 36 hours the next under a two-week averaging arrangement. What is the correct outcome?', '[{"id": "A", "text": "Two hours of overtime are owed for the first week, because it exceeded 38 hours"}, {"id": "B", "text": "No overtime is owed, because the total of 76 hours averages exactly 38 hours per week over the cycle"}, {"id": "C", "text": "The two extra hours must be banked as time off in lieu in the second week"}, {"id": "D", "text": "Overtime is owed for the first week and the second week must be topped up to 38 hours"}]', '{"choice_id": "B"}', 'The video states that 40 plus 36 equals 76 hours, exactly 38 times two, so no overtime is owed for the longer week because the arrangement allows it to average out over the cycle.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:28.774306+00', '2026-07-30 08:16:28.774306+00', '651cf018-f066-4671-94f6-bf3d9c961875', '9774a47c04319975246e6d003da38dd7babddbaf24eff08e25164a25f089ffe9');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6bc8d5e0-74d0-4ea9-bde4-65af7dd35d65', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'According to the video, what is the critical mistake to avoid when an averaging arrangement applies?', '[{"id": "A", "text": "Assuming overtime applies because a single week in isolation shows a big number of hours"}, {"id": "B", "text": "Paying the employee for every hour actually worked"}, {"id": "C", "text": "Using a four-week cycle instead of a two-week cycle"}, {"id": "D", "text": "Allowing the daily distribution of hours to vary across the week"}]', '{"choice_id": "A"}', 'The video warns against looking at a single week in isolation and assuming a big number means overtime — you need the total across the whole agreed cycle first.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:28.774306+00', '2026-07-30 08:16:28.774306+00', '651cf018-f066-4671-94f6-bf3d9c961875', '9774a47c04319975246e6d003da38dd7babddbaf24eff08e25164a25f089ffe9');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('16e7aaec-8496-4f8b-b85c-ab0f16eebdd1', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'What does the video say about averaging periods across different awards?', '[{"id": "A", "text": "All modern awards use a standard four-week averaging period"}, {"id": "B", "text": "Averaging periods are always two weeks unless the employee agrees otherwise"}, {"id": "C", "text": "They vary — two, three or four weeks — so you must check the specific award"}, {"id": "D", "text": "The averaging period is set by the employer''s payroll cycle"}]', '{"choice_id": "C"}', 'The video says to check your award for its specific averaging period — two weeks, three weeks, four weeks — because they are not all the same.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:28.774306+00', '2026-07-30 08:16:28.774306+00', '651cf018-f066-4671-94f6-bf3d9c961875', '9774a47c04319975246e6d003da38dd7babddbaf24eff08e25164a25f089ffe9');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('1825c607-b2a6-4f6c-9cbd-af411ae15490', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'easy', 'According to the video, how many modern awards are there in Australia?', '[{"id": "A", "text": "22"}, {"id": "B", "text": "122"}, {"id": "C", "text": "183"}, {"id": "D", "text": "1,100"}]', '{"choice_id": "B"}', 'The video states that modern awards cover most working Australians and that there are 122 of them.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:45.446619+00', '2026-07-30 08:16:45.446619+00', '3fa8c12f-29ff-415c-a95b-f602e94402cc', 'e791f112f8b3e829f4e126fe19e018199fdf1a567f633bb9314c1b4d933b7d5d');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6d1a472e-dd5d-4ab1-9f46-c607d23f1116', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'The video recommends a particular sequence for identifying which award applies. What is it?', '[{"id": "A", "text": "Check the employee''s job title first, then the contract wording"}, {"id": "B", "text": "Check occupation first, then fall back to the employer''s industry"}, {"id": "C", "text": "Check the employer''s industry first, then fall back to occupation where appropriate, and document the conclusion"}, {"id": "D", "text": "Ask the employee which award they believe applies, then confirm with the Fair Work Commission"}]', '{"choice_id": "C"}', 'The video says the safest approach is to test industry first, then fall back to occupation where appropriate, and document why you reached that conclusion.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:45.446619+00', '2026-07-30 08:16:45.446619+00', '3fa8c12f-29ff-415c-a95b-f602e94402cc', 'e791f112f8b3e829f4e126fe19e018199fdf1a567f633bb9314c1b4d933b7d5d');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('e49c9583-6088-47fe-aa53-604d5ec6dbb6', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'easy', 'What figure does the video give as the high-income threshold from 1 July 2025 for the award coverage exception?', '[{"id": "A", "text": "$175,000"}, {"id": "B", "text": "$183,100"}, {"id": "C", "text": "$167,500"}, {"id": "D", "text": "$190,800"}]', '{"choice_id": "B"}', 'The video states that for this module the high-income threshold is $183,100 from 1 July 2025, applying where there is a written guarantee of annual earnings above it.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:16:45.446619+00', '2026-07-30 08:16:45.446619+00', '3fa8c12f-29ff-415c-a95b-f602e94402cc', 'e791f112f8b3e829f4e126fe19e018199fdf1a567f633bb9314c1b4d933b7d5d');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6d0db0e5-3b9c-49ef-9ee6-adcc5e57ad89', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'easy', 'According to the video, how often can compassionate (bereavement) leave under the NES be accessed?', '[{"id": "A", "text": "Once per year only, regardless of how many qualifying events occur"}, {"id": "B", "text": "Every time a qualifying event occurs — it is not capped once per year"}, {"id": "C", "text": "Twice per year, then only as unpaid leave"}, {"id": "D", "text": "Only once during an employee''s total period of employment"}]', '{"choice_id": "B"}', 'The video states the entitlement is a small number of days per occasion and applies every time a qualifying event occurs, rather than being capped once per year.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:12.105893+00', '2026-07-30 08:17:12.105893+00', 'c02336dd-c448-48de-8e1b-b136db36f84a', 'a3e40dda2f927fb63304a2e866626f5a748af25bf4ccf1b303a86dc7d5663e37');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('44f750e5-cf87-455d-a494-da4ea26fcd98', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'Which events does the video identify as triggering the NES compassionate leave entitlement?', '[{"id": "A", "text": "Only the death of a member of the immediate family"}, {"id": "B", "text": "The death, or a life-threatening illness or injury, of a member of the employee''s immediate family or household"}, {"id": "C", "text": "Any hospital admission of a relative, however minor"}, {"id": "D", "text": "The death of any person the employee names on a leave form"}]', '{"choice_id": "B"}', 'The transcript says the entitlement arises when a member of the immediate family or household passes away, or suffers a life-threatening illness or injury.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:12.105893+00', '2026-07-30 08:17:12.105893+00', 'c02336dd-c448-48de-8e1b-b136db36f84a', 'a3e40dda2f927fb63304a2e866626f5a748af25bf4ccf1b303a86dc7d5663e37');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('515fc2ef-8761-410c-b03c-28a6acf2151c', '3883edda-864c-416e-8127-83bd7d28a5a2', 'payroll', 'medium', 'How does the video describe the scope of ''member of the family'' for compassionate leave?', '[{"id": "A", "text": "Strictly limited to blood relatives only"}, {"id": "B", "text": "Unlimited — any person the employee considers important qualifies"}, {"id": "C", "text": "Extends beyond immediate blood relatives (including household members or family under cultural or community understandings), but not to acquaintances or distant connections"}, {"id": "D", "text": "Limited to spouse or partner and children only"}]', '{"choice_id": "C"}', 'The video says the definition reasonably stretches to household members and people considered family under cultural or community understandings, while acquaintances or distant connections generally will not qualify.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:12.105893+00', '2026-07-30 08:17:12.105893+00', 'c02336dd-c448-48de-8e1b-b136db36f84a', 'a3e40dda2f927fb63304a2e866626f5a748af25bf4ccf1b303a86dc7d5663e37');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('92cc4c9d-ece7-408d-be19-636840d40b1b', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'easy', 'Per the video, what should payroll do when there is genuine doubt about whether a person qualifies as ''family'' for compassionate leave?', '[{"id": "A", "text": "Apply the narrowest reasonable reading of ''family'' and decline the leave"}, {"id": "B", "text": "Approve the leave as unpaid until documentation is produced"}, {"id": "C", "text": "Refer the case to HR to discuss with the employee, then correctly apply and pay whatever determination is made"}, {"id": "D", "text": "Convert the request to annual leave to avoid the risk"}]', '{"choice_id": "C"}', 'The transcript states genuinely uncertain cases are a conversation for HR with the employee, and payroll''s job is to correctly apply and pay the determination made rather than making a restrictive call unilaterally.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:12.105893+00', '2026-07-30 08:17:12.105893+00', 'c02336dd-c448-48de-8e1b-b136db36f84a', 'a3e40dda2f927fb63304a2e866626f5a748af25bf4ccf1b303a86dc7d5663e37');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5048e51d-7583-4fef-b182-352d9d983ce0', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'easy', 'According to the video, what does the BMS ID stand for and identify?', '[{"id": "A", "text": "Business Management System ID — the identifier tied to your specific payroll software"}, {"id": "B", "text": "Business Migration Service ID — the identifier issued when data is transferred between systems"}, {"id": "C", "text": "Basic Member Superannuation ID — the identifier for an employee''s super fund"}, {"id": "D", "text": "Business Monthly Submission ID — a unique number generated for each pay run"}]', '{"choice_id": "A"}', 'The video states the BMS ID is the business management system ID, the identifier tied to your specific payroll software, which the ATO uses to associate data with the right software instance and business.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:29.379892+00', '2026-07-30 08:17:29.379892+00', 'a55f6135-54de-4a3c-a102-f803f9583f19', '494735a381a1d8a055c5d2684809432766987827752a066b00ebc4dd275955a3');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('7d48d661-e520-4656-a532-283ac2b6999e', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'The video says employees can log into myGov during the year and see year-to-date income building up. What does it contrast this with?', '[{"id": "A", "text": "Receiving a payslip each pay period"}, {"id": "B", "text": "Waiting for an end-of-year payment summary"}, {"id": "C", "text": "Requesting a letter of employment from payroll"}, {"id": "D", "text": "Lodging a tax return to confirm earnings"}]', '{"choice_id": "B"}', 'The transcript notes STP means employees can see year-to-date income in myGov at any time rather than waiting for an end-of-year payment summary.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:29.379892+00', '2026-07-30 08:17:29.379892+00', 'a55f6135-54de-4a3c-a102-f803f9583f19', '494735a381a1d8a055c5d2684809432766987827752a066b00ebc4dd275955a3');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('f27e888f-2836-4b98-809c-c4946e3ffc70', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'medium', 'Which situations does the video identify as when the BMS ID matters practically?', '[{"id": "A", "text": "When an employee changes tax file number declarations or bank details"}, {"id": "B", "text": "When a business processes a pay run out of cycle or reverses a pay"}, {"id": "C", "text": "When a business changes payroll systems, migrates data, or splits into multiple entities using different software"}, {"id": "D", "text": "When an award rate increase is applied at the start of a new financial year"}]', '{"choice_id": "C"}', 'The video specifically lists changing payroll systems, migrating data, or splitting into multiple entities using different software as the situations where the BMS ID matters.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:29.379892+00', '2026-07-30 08:17:29.379892+00', 'a55f6135-54de-4a3c-a102-f803f9583f19', '494735a381a1d8a055c5d2684809432766987827752a066b00ebc4dd275955a3');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('a416bc82-d910-4aa5-9fed-f92fc444da88', '1bf86cf5-916c-4177-a96a-f249059c71b6', 'payroll', 'easy', 'What does the video say a payroll professional''s practical responsibility is regarding the BMS ID?', '[{"id": "A", "text": "Manually generate and record a new BMS ID at the start of each financial year"}, {"id": "B", "text": "Reconcile the BMS ID against each employee''s myGov record before finalising"}, {"id": "C", "text": "Not manage it day to day, but flag it as a question with the software provider during a system change or migration"}, {"id": "D", "text": "Apply to the ATO for a replacement BMS ID whenever a mismatch occurs"}]', '{"choice_id": "C"}', 'The video says the BMS ID is largely handled by the software itself and payroll doesn''t manage it day to day, but you should ask your software provider how it is being handled through any system change or migration.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:29.379892+00', '2026-07-30 08:17:29.379892+00', 'a55f6135-54de-4a3c-a102-f803f9583f19', '494735a381a1d8a055c5d2684809432766987827752a066b00ebc4dd275955a3');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5317d016-4fe5-4366-8448-72ef2658b199', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'easy', 'According to the video, what distinguishes an expense-related allowance from a wage-related allowance?', '[{"id": "A", "text": "An expense-related allowance reimburses money the employee is expected to spend themselves, while a wage-related allowance compensates for a duty or working condition"}, {"id": "B", "text": "An expense-related allowance is paid annually, while a wage-related allowance is paid each pay period"}, {"id": "C", "text": "An expense-related allowance is set by the contract, while a wage-related allowance is set by the award"}, {"id": "D", "text": "An expense-related allowance is always taxable, while a wage-related allowance never is"}]', '{"choice_id": "A"}', 'The video states expense-related allowances exist to reimburse the employee for money they are expected to spend themselves, whereas a wage-related allowance compensates for a duty or working condition.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:49.342055+00', '2026-07-30 08:17:49.342055+00', '5d10af49-3257-46ac-877b-fa03d18d7342', '12676cba99fcf8f63b2a5a0be39c394b20c79a9fc7d9a75b871db10d9626285c');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6b206136-1f20-4bcf-9a95-d2d9aa1b6541', '803a42f9-943e-492d-ad1e-d9e9516b27c2', 'payroll', 'medium', 'The video says a tradesperson expected to supply their own tools is often entitled to a tool allowance under the award. What does it say about the contract in that situation?', '[{"id": "A", "text": "The contract overrides the award if it is more recent"}, {"id": "B", "text": "The award entitlement applies regardless of what the contract says"}, {"id": "C", "text": "The allowance is only payable if the contract expressly mentions tools"}, {"id": "D", "text": "The employee must waive the contract term before the allowance applies"}]', '{"choice_id": "B"}', 'The video states the award entitlement to a tool allowance applies regardless of what the contract says, because it compensates for a genuine expense the employee is carrying.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:49.342055+00', '2026-07-30 08:17:49.342055+00', '5d10af49-3257-46ac-877b-fa03d18d7342', '12676cba99fcf8f63b2a5a0be39c394b20c79a9fc7d9a75b871db10d9626285c');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('60a0474c-4595-45ad-888f-4d48bfa663e0', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'How does the video describe the tax treatment of genuine reimbursements of actual expenses and award-based allowances up to the ATO''s reasonable limits?', '[{"id": "A", "text": "Fully taxable and reportable as ordinary income"}, {"id": "B", "text": "Taxable but not reportable"}, {"id": "C", "text": "Typically not taxable and not reportable"}, {"id": "D", "text": "Not taxable but always reportable on the income statement"}]', '{"choice_id": "C"}', 'The video says genuine reimbursements of actual expenses, and award-based allowances up to the ATO''s reasonable limits, are typically not taxable and not reportable.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:49.342055+00', '2026-07-30 08:17:49.342055+00', '5d10af49-3257-46ac-877b-fa03d18d7342', '12676cba99fcf8f63b2a5a0be39c394b20c79a9fc7d9a75b871db10d9626285c');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('3b1dc49e-0025-4f19-997c-2c6474d5d829', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'easy', 'What does the video say happens if a payment is labelled an allowance but is really just extra salary with no real connection to an employee expense?', '[{"id": "A", "text": "The ATO will treat it as ordinary income, fully taxable"}, {"id": "B", "text": "It remains exempt provided it is under the ATO''s reasonable limit"}, {"id": "C", "text": "It is reportable but not taxable"}, {"id": "D", "text": "It becomes the employee''s responsibility to declare and correct"}]', '{"choice_id": "A"}', 'The video states that where a payment is dressed up as an allowance but has no real connection to an employee expense, the ATO will treat it as ordinary income that is fully taxable.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:17:49.342055+00', '2026-07-30 08:17:49.342055+00', '5d10af49-3257-46ac-877b-fa03d18d7342', '12676cba99fcf8f63b2a5a0be39c394b20c79a9fc7d9a75b871db10d9626285c');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('01966ccd-d47e-477a-aab8-010f7e31768f', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'What order of steps does the video recommend when handling a retroactive rate increase?', '[{"id": "A", "text": "Determine the tax withholding method first, then calculate the gross owed"}, {"id": "B", "text": "Calculate the gross owed and the tax treatment simultaneously in one step"}, {"id": "C", "text": "Work out the correct gross amount owed based on hours and rate difference, then apply the appropriate tax withholding method"}, {"id": "D", "text": "Pay the full new rate for all hours, then reconcile the overpayment at year end"}]', '{"choice_id": "C"}', 'The video says to keep the calculation separate from tax treatment: work out the correct gross first based purely on hours and rate difference, then move on to how it should be taxed.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:04.727484+00', '2026-07-30 08:18:04.727484+00', '4e16dd93-7e2d-4e26-b1fd-7811c32386d4', '0857df3aee68e31f556f6d1d620868c5fceb8108e077114fc30f8bce9e7fe314');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('97c78368-46fb-41b7-abac-ff0f2fdd73c3', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'easy', 'How does the video describe this back pay scenario compared with termination or unused-leave back pay calculations?', '[{"id": "A", "text": "It is the same calculation, just applied over multiple pay periods"}, {"id": "B", "text": "It is a distinct exercise, because the employee has simply been paid at the old lower rate for hours already worked"}, {"id": "C", "text": "It replaces the termination calculation whenever a rate rises"}, {"id": "D", "text": "It only applies to employees who have already been terminated"}]', '{"choice_id": "B"}', 'The video opens by noting this is a distinct exercise from taxing a termination back pay: here the employee was simply paid at the old, lower rate for hours already worked and a new rate now applies retroactively.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:04.727484+00', '2026-07-30 08:18:04.727484+00', '4e16dd93-7e2d-4e26-b1fd-7811c32386d4', '0857df3aee68e31f556f6d1d620868c5fceb8108e077114fc30f8bce9e7fe314');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('5e8ab970-21e1-4efb-b1bb-505c0a229753', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'In the example given in the video, an employee should have been paid $55 an hour for 38 hours in a pay period. How is the final gross for that period made up?', '[{"id": "A", "text": "The original payment plus the calculated top-up"}, {"id": "B", "text": "$55 multiplied by 38, plus the original payment"}, {"id": "C", "text": "Only the top-up amount, paid as a separate payment"}, {"id": "D", "text": "38 hours at the old rate plus a loading percentage"}]', '{"choice_id": "A"}', 'The video explains the back pay (hourly difference × 38 hours) is added to what was originally paid, so the final gross reflects the new rate in full made up of the original payment plus the top-up.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:04.727484+00', '2026-08-31 01:44:31.90033+00', '4e16dd93-7e2d-4e26-b1fd-7811c32386d4', '0857df3aee68e31f556f6d1d620868c5fceb8108e077114fc30f8bce9e7fe314');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('9de75f6b-77d4-4782-9a75-5ed2e59e1306', '5257034c-4993-4cb7-b3da-836bf085e9f0', 'payroll', 'easy', 'According to the video, if in a given month an employee''s work is carried out across two or more states, in which state does the payroll tax liability sit?', '[{"id": "A", "text": "The state where the employer''s head office is registered"}, {"id": "B", "text": "The state where the employee resides"}, {"id": "C", "text": "The state where the greatest proportion of the work was performed"}, {"id": "D", "text": "The liability is split equally between all states involved"}]', '{"choice_id": "B"}', 'The video states that where work is carried out wholly in one state the employer is liable in that state, but where work spans two or more states, liability sits in the state where the employee resides.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:18:19.342438+00', '2026-07-30 08:18:19.342438+00', 'e823b48a-3477-4085-9e1a-5c20667ef7fc', 'afc9f22dc10ed3200d8a61e74ef1ee7673e6557aaf2c3588676be17fc36c3fea');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('2e605941-d10a-453a-b131-928df59cf4be', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'easy', 'According to the video, how many pay periods a year are used to calculate fortnightly, weekly and monthly pay respectively?', '[{"id": "A", "text": "24, 48 and 12"}, {"id": "B", "text": "26, 52 and 12"}, {"id": "C", "text": "26, 52 and 13"}, {"id": "D", "text": "27, 52 and 12"}]', '{"choice_id": "B"}', 'The video states fortnightly is calculated on 26 pay periods a year, weekly on 52 and monthly on 12.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:19:22.302069+00', '2026-07-30 08:19:22.302069+00', 'f4f35cb4-a1b9-477f-8819-c9748380d195', 'b223637fb78f2037f54219062a7d678b1f5db6a36cf5b6b8fb35b2ddd3799512');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('d68a273c-ea3e-41e9-8ca6-01fb9b8a4e38', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'The video says the number of pay periods in a year feeds directly into which of the following?', '[{"id": "A", "text": "Tax table selection and various per-period calculations"}, {"id": "B", "text": "Superannuation guarantee percentage"}, {"id": "C", "text": "The employee''s leave entitlement balance in weeks"}, {"id": "D", "text": "The employer''s payroll tax liability"}]', '{"choice_id": "A"}', 'The video explains that the number of pay periods in a year feeds directly into tax table selection and various per-period calculations, and a wrong number compounds errors in every subsequent calculation.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:19:22.302069+00', '2026-07-30 08:19:22.302069+00', 'f4f35cb4-a1b9-477f-8819-c9748380d195', 'b223637fb78f2037f54219062a7d678b1f5db6a36cf5b6b8fb35b2ddd3799512');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('6cffa226-ce12-408e-b344-e991f76f4966', '3945b6f4-ba83-46c3-b2ac-19eae813064b', 'payroll', 'medium', 'Why does the video stress communicating a pay frequency change to the employee well ahead of time?', '[{"id": "A", "text": "Because Fair Work requires 12 weeks'' written notice of any pay date change"}, {"id": "B", "text": "Because the employee must repay any overpayment before the change takes effect"}, {"id": "C", "text": "Because the transition period can result in an unusually large or small payment that looks like an error if nobody has been told to expect it"}, {"id": "D", "text": "Because the employee''s tax file number declaration must be re-lodged"}]', '{"choice_id": "C"}', 'The video notes the transition period can produce an unusually large or small payment, which can look like an error unless the employee has been told when the pay date shifts and what the first new payment will look like.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:19:22.302069+00', '2026-07-30 08:19:22.302069+00', 'f4f35cb4-a1b9-477f-8819-c9748380d195', 'b223637fb78f2037f54219062a7d678b1f5db6a36cf5b6b8fb35b2ddd3799512');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('db226da7-96a0-480b-ac5e-9de6757faee1', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'medium', 'Beyond the payroll system settings, what does the video say must be confirmed before processing a pay frequency change?', '[{"id": "A", "text": "That the ATO has approved the new pay cycle in writing"}, {"id": "B", "text": "That the award or contract actually permits the change, since some awards specify payment frequency or set conditions around changing it"}, {"id": "C", "text": "That the change takes effect from the start of a new financial year"}, {"id": "D", "text": "That the employee''s super fund accepts contributions at the new frequency"}]', '{"choice_id": "B"}', 'The video warns that some awards specify payment frequency directly or set conditions around when it can change, so you must confirm the change is permitted, not just technically possible in the system.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:19:22.302069+00', '2026-07-30 08:19:22.302069+00', 'f4f35cb4-a1b9-477f-8819-c9748380d195', 'b223637fb78f2037f54219062a7d678b1f5db6a36cf5b6b8fb35b2ddd3799512');
INSERT INTO payroll_iq.questions (id, topic_id, track, difficulty, question_text, options, correct_answer, explanation, mastery_weight, source, status, authored_by, created_at, updated_at, generated_from_module_id, source_transcript_hash) VALUES ('068e9b79-770f-4d00-b044-e34aa5d1882c', '61a549a2-eaa8-4c00-89cd-5b1a4d0ca4a2', 'payroll', 'easy', 'According to the video, to whom must an employer send child support amounts withheld from an employee''s pay?', '[{"id": "A", "text": "The Australian Taxation Office"}, {"id": "B", "text": "Services Australia"}, {"id": "C", "text": "The Fair Work Ombudsman"}, {"id": "D", "text": "The receiving parent directly"}]', '{"choice_id": "B"}', 'The video states that child support deductions are withheld and sent to Services Australia on behalf of the paying parent.', 1.0, 'ai', 'draft', NULL, '2026-07-30 08:19:37.917904+00', '2026-07-30 08:19:37.917904+00', '28e6b8ac-6afa-40df-9812-cb82b675feea', 'be42f59b4bdc9f312d63d2d35dfcf1753fb78e7ef94b28ab1365e1156f849b2f');
